(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["rl"]||{};var a=d["papers"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="paper-understanding-sampler-stochasticity-2025"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-1\">一 · 现场：一个 7×24 在线 RLHF 服务的凌晨三点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-2\">二 · 旧方案的主流做法：随机性被折叠进“实现细节”</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-3\">三 · 为什么非改不可：奖励信号的可复现性是 SLO 的前置条件</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-4\">四 · 三类随机性来源与它们在推理栈里的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-5\">五 · 异步流水线与权重同步：屏障是随机性隔离的最后一道</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-6\">六 · 对 Blackwell 部署的直接含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-7\">七 · 请求形态的测量口径：先把“长度分布”变成可核验的量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-8\">八 · 并发与批大小：批级随机状态是并发的计量单位</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-9\">九 · SLO 与长尾：长尾样本的二次推理是延迟预算的隐藏项</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-10\">十 · 负载塑造方案：分桶、屏障与缓存路径的相互约束</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-11\">十一 · 方案反过来限制负载：屏障与批级记录如何压缩可调度空间</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-12\">十二 · 批级随机状态作为负载契约：分桶、屏障与长尾的代价边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-13\">十三 · 从采样方程到 kernel：随机性在寄存器里长什么样</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-14\">十四 · 数据类型选择：FP16/BF16 的稳定性边界与 FP8/NVFP4 的压缩代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-15\">十五 · 累加精度：TMEM 里的误差如何进入奖励打分</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core 的推理含义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-17\">十七 · 数值策略与随机性控制的联合设计</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-18\">十八 · 随机状态元数据在 Blackwell 精度链路上的边界与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-19\">十九 · 显存账本的三个账户与扩散 rollout 的记账口径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-20\">二十 · 分页与前缀共享：随机性隔离如何改变缓存布局</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-21\">二十一 · 压缩、复用与卸载：三条路径的带宽代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-22\">二十二 · 带宽瓶颈定位：HBM3e 容量与带宽的复算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-23\">二十三 · 可复算的显存预算：从单批到整柜</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-24\">二十四 · 与随机性控制的耦合点：屏障、命中率与失败模式</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-25\">二十五 · 前缀共享 KV 的显存账本与随机性隔离的代价边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-26\">二十六 · 连续批处理：批边界由随机状态而非请求到达决定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-27\">二十七 · Chunked prefill：前缀共享 KV 与随机性隔离的交叉点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-28\">二十八 · 优先级与抢占：长尾样本与权重同步屏障的冲突</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-29\">二十九 · 分离式预填/解码：奖励模型服务的接入形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-30\">三十 · 尾延迟怎么压：批级记录、屏障粒度与监控闭环</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-31\">三十一 · 随机状态与批级屏障：调度边界、失效条件与系统代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-32\">三十二 · 并行拓扑与随机状态的可复现边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-33\">三十三 · NVLink 5 与 NVSwitch：集合通信的物理下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-34\">三十四 · All-to-All 与 EP：路由带来的非对称流量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-35\">三十五 · NIXL 传输与分离式预填/解码的通信账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-36\">三十六 · 通信成为瓶颈的判据与批级屏障的取舍</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-37\">三十七 · 随机性屏障落进并行拓扑之后：边界、失效与代价</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-38\">三十八 · 精度塌陷：从随机状态漂移到奖励信号失真</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-39\">三十九 · OOM与批抖动：批大小、KV复用与屏障点的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-40\">四十 · 尾延迟：长尾样本与验证器二次推理的放大效应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-41\">四十一 · 静默降级：监控指标的选择与误判</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-42\">四十二 · 定位与回滚：屏障点作为可回滚的控制面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-43\">四十三 · 批级屏障失效与随机状态泄漏的定位路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-44\">四十四 · 基准口径的三层结构：论文没给的，部署必须自己定</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-45\">四十五 · 硬件档位与精度路径：外推区的边界在哪</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-46\">四十六 · batch 与并发：分桶决定了一切数字的分母</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-47\">四十七 · 指标怎么读：TTFT/TPOT 在扩散 rollout 里的语义偏移</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-48\">四十八 · 哪些提升不可比：四类典型陷阱</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-49\">四十九 · 把口径写进监控：可执行的验收清单</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-50\">五十 · 迁移到非扩散生成范式时的机制改写</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-51\">五十一 · 与量化精度叠加时的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-52\">五十二 · 规模上限：屏障频率与长尾吞吐的张力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-53\">五十三 · 不适用的场景与判断线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-54\">五十四 · 跨领域迁移的形态差异</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"paper-understanding-sampler-stochasticity-2025-sec-55\">五十五 · 边界判定：随机性控制方案的适用域与失效条件</button></li></ol></nav><figure class=\"diagram\" data-fig=\"paper-pipeline\"><svg style=\"max-width:552px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 552.3 423\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"470.3\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">请求进入rollout引擎，按提示长度与批大小排队，随机种子写入请求元…</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"470.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">扩散采样按固定噪声调度执行，批内样本共享前缀KV但各自保留随机状态。</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"470.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">生成样本送入奖励模型服务，分离式预填与解码按批聚合打分。</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"470.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">验证器对长尾样本二次推理，结果回写批级随机状态记录。</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"470.3\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">异步流水线在权重同步点做屏障，丢弃跨版本随机状态。</text><line x1=\"82.0\" y1=\"342.2\" x2=\"82.0\" y2=\"359.2\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 358.2 L 86.5 358.2 L 82.0 366.2 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"366.2\" width=\"470.3\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"388.7\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"392.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">6</text><text x=\"75.0\" y=\"393.9\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">批级吞吐与随机性指标上报监控，供SLO判定。</text></svg><figcaption><b>流水线</b> · 从输入到输出的数据流；每一步的模块与代价在正文展开。</figcaption></figure>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-1\">一 · 现场：一个 7×24 在线 RLHF 服务的凌晨三点</h3>\n<p>设想一个已经上线的对齐服务：前端是对话接口，后端是 GB200 NVL72 机柜里的一组 B200 计算托盘。用户请求先进入 rollout 引擎做扩散采样，样本随即被送进奖励模型服务打分，长尾样本再走验证器二次推理，打分结果回灌到策略更新闭环。白天流量平稳时，这套流水线看起来一切正常；到了凌晨，调度器把批大小从保守值拉高，提示长度分桶重新切分，异步流水线在权重同步点前后出现了几秒钟的版本交错。运维看到的第一个异常不是崩溃，而是奖励分数分布的漂移：同一个提示，在相邻两个批次里的奖励均值出现了不该有的偏移，长尾样本的通过率忽高忽低，SLO 面板上的批级吞吐曲线开始抖动。</p>\n<p>这类漂移的根源不在奖励模型本身，而在扩散采样器。扩散采样每一步都要注入噪声，步进离散化把连续时间切成有限步，批内样本又共享前缀 KV 缓存。三者叠加，使“同一提示、同一权重”在不同批次、不同随机种子下生成的样本分布并不相同。旧方案把这件事当作实现细节：随机种子不落元数据，批内共享缓存不做隔离，权重同步点不设屏障。于是奖励模型看到的输入分布随批次变化，策略更新拿到的奖励信号被污染，异步流水线里的长尾吞吐无法稳定评估。对在线服务而言，这不是数值精度问题，而是可复现性问题——它直接决定 SLO 能不能守住。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-2\">二 · 旧方案的主流做法：随机性被折叠进“实现细节”</h3>\n<p>论文之前，扩散 RLHF 推理栈的主流做法可以概括为三条默认约定。第一，rollout 引擎按提示长度分桶、按显存与延迟目标确定批大小，批内样本共享前缀 KV 以压低预填代价；第二，采样器使用一套全局噪声调度，随机种子由框架默认生成，不写入请求元数据；第三，奖励模型与验证器以分离式预填/解码接入，异步流水线靠时间窗口而非批级屏障来对齐权重版本。这三条约定各自都合理，合在一起却把随机性折叠成了不可追踪的实现细节。</p>\n<p>从系统代价看，旧方案的收益是明确的：前缀共享 KV 把批内重复前缀的预填计算摊薄，分离式预填/解码让奖励模型服务与 rollout 引擎解耦，异步流水线把权重同步的停顿藏在长尾样本的推理时间里。代价则是隐性的：随机种子不落元数据，意味着任何一次分布漂移都无法回溯到具体批次；批内共享缓存不做随机性隔离，意味着批内样本因缓存耦合而失去独立性；权重同步点缺少批级屏障，意味着旧版本的随机状态会泄漏到新策略的奖励打分中。这三项代价在吞吐面板上不可见，只在奖励信号的质量上体现。</p>\n<table class=\"mini\"><thead><tr><th>旧方案约定</th><th>换来的收益</th><th>隐藏代价</th></tr></thead><tbody><tr><td>批内前缀共享 KV</td><td>预填计算摊薄、显存占用下降</td><td>批内样本随机性耦合，独立性丢失</td></tr><tr><td>全局噪声调度、种子不落元数据</td><td>引擎实现简单、调度器无额外状态</td><td>分布漂移不可回溯，奖励信号跨批次漂移</td></tr><tr><td>时间窗口对齐权重版本</td><td>异步流水线吞吐平滑</td><td>旧版本随机状态泄漏进新策略打分</td></tr></tbody></table>\n<p>一个具体例子：某批 32 条请求共享一段长系统提示，前缀 KV 只算一次，预填成本降到单条请求的零头。但采样阶段批内样本各自注入噪声时，共享缓存路径上的随机状态被复用，样本之间的差异被压缩，奖励模型收到的是 32 条高度相关的样本。奖励均值的方差被人为压低，策略更新误以为这一批的奖励信号很稳定，实际上下一次换批、换种子后分布立刻回摆。工程上这就是“奖励信号被缓存耦合污染”的典型形态。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-3\">三 · 为什么非改不可：奖励信号的可复现性是 SLO 的前置条件</h3>\n<p>把问题形式化，RL 后训练的目标是</p>\n<div class=\"formula\">$$\\mathcal{L}(\\theta)=\\mathbb{E}_{x\\sim p_{\\text{rollout}}(\\cdot\\mid c;\\xi)}\\left[r_{\\phi}(x)\\right],\\quad \\xi\\sim\\mathcal{N}(0,I)$$</div>\n<p>其中 $\\xi$ 是采样随机性。旧方案的问题在于 $p_{\\text{rollout}}$ 对 $\\xi$ 的依赖没有被记录，期望算子在实际系统中退化成“这一批碰巧采到的样本均值”。当批大小、分桶边界、权重版本任一变化，$\\xi$ 的分布随之变化，$r_{\\phi}(x)$ 的输入分布跟着漂移，策略更新拿到的梯度方向就不再是同一个目标函数的梯度。对在线服务，这意味着奖励模型的打分不可复现，验证器的长尾判定不可复现，SLO 里的通过率指标失去统计意义。</p>\n<p>代价可以从三个维度量化定性。延迟侧：若为了消除漂移而强行串行化采样、禁用前缀共享，预填成本回到逐条计算，批级吞吐显著下降，长尾样本的排队时间被拉长。显存侧：若为每条请求保留独立 KV 而不共享前缀，KV 占用随批大小线性上升，在 B200 的 HBM 容量下可用批大小被压缩，吞吐与显存形成直接对冲。带宽侧：随机状态若随请求元数据全量传递而不做批级聚合，元数据通路与奖励模型服务的输入通路都要承载额外流量，在 NVL72 机柜内的 NVLink 5 域里这部分开销虽小，但在跨节点分离式部署中会放大。三项代价的共同点是：它们都不是免费消除的，必须靠机制设计把随机性“显式化”而非“消灭”。</p>\n<p>论文的判断正是如此：采样随机性不是要消除的噪声，而是要记录和控制的状态。固定噪声调度让 $\\xi$ 的注入路径确定；按批记录随机状态让每次采样的 $\\xi$ 可回溯；对前缀共享 KV 复用路径做随机性隔离，让批内样本在共享缓存的同时保持独立。这三件事合起来，才使 $p_{\\text{rollout}}$ 在工程上可复现，奖励信号才配得上作为策略更新的输入。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-4\">四 · 三类随机性来源与它们在推理栈里的落点</h3>\n<p>论文把扩散采样随机性拆成三类来源，每一类在推理栈里都有明确的落点。噪声注入：每一步采样注入的高斯噪声，其种子若由框架默认生成而不落元数据，就无法在奖励模型侧复现同一样本。步进离散化：连续时间被切成有限步，步数与调度决定样本落在分布的那个区域，不同批次的步进边界若不一致，样本分布自然漂移。批内耦合：前缀共享 KV 让批内样本走同一缓存路径，随机状态若随缓存复用而耦合，样本独立性被破坏。</p>\n<p>对应的控制点也在推理栈里：rollout 引擎按提示长度分桶并确定批大小后，为每条请求分配随机种子并写入元数据；扩散采样在前缀共享 KV 上推进时，批内样本各自维护噪声状态，共享缓存但不共享随机状态；生成完成后，样本连同随机状态送入奖励模型服务，分离式预填与解码按批聚合打分；长尾样本进入验证器二次推理，结果回写批级记录。伪代码思路可以写成：</p>\n<div class=\"formula\">$$\\text{for } b \\text{ in batch: } \\xi_b \\leftarrow \\text{seed}(req_b);\\ \\text{sample}(x_b \\mid c, \\xi_b, \\text{KV}_{\\text{shared}});\\ \\text{record}(b, \\xi_b)$$</div>\n<p>这里的工程代价是显式的：每条请求多一份随机状态元数据，批级记录多一次回写，验证器多一轮二次推理。换来的收益是奖励模型看到的样本分布可复现，长尾吞吐可评估。一个具体例子：同一提示在批 A 与批 B 中分别采样，若两批的随机种子都落元数据，运维可以在奖励分数漂移时直接定位到是种子分配策略变了还是分桶边界变了，而不是在一堆不可复现的样本里猜。这正是旧方案做不到、新机制必须做的事。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-5\">五 · 异步流水线与权重同步：屏障是随机性隔离的最后一道</h3>\n<p>旧方案用时间窗口对齐权重版本，问题是窗口内的请求可能跨越两个策略版本。扩散采样在旧版本权重下注入的随机状态，若随样本流入新版本的奖励打分，就构成 off-policy 陈旧样本污染。论文的做法是在异步流水线的权重同步点设置批级屏障：屏障之前的批次用旧版本随机状态完成打分并归档，屏障之后的批次用新版本重新分配种子，跨版本的随机状态被丢弃而不泄漏。</p>\n<p>这道屏障的系统代价是同步停顿：屏障点上的批必须等齐，长尾样本的二次推理若拖尾，屏障就把拖尾放大成整批的等待。对 GB200 NVL72 这类机柜级部署，屏障点若设在跨节点边界，NCCL 集合通信的同步开销会叠加进来；若设在单节点内，NVLink 5 域内的同步代价可控，但跨节点的奖励模型服务仍要面对分离式预填/解码的输入聚合。工程判断是：屏障粒度要跟批大小和长尾占比匹配，批太大则停顿被放大，批太小则屏障频繁触发、吞吐抖动。论文没有给出具体数字，只给出机制——批级屏障隔离跨版本随机状态，监控侧上报批级吞吐、随机状态命中率与长尾占比，供 SLO 判定与失败模式定位。</p>\n<p>一个具体失败模式值得记住：若屏障只按时间窗口设而不按批设，长尾样本可能在屏障之后才完成二次推理，其随机状态来自旧版本，回写时污染新批级的记录。监控上的表现是随机状态命中率在权重同步前后出现凹陷，长尾占比在同一窗口内抬升。这类失败不会让服务宕机，但会让奖励信号在版本切换处出现系统性偏差，正是旧方案最难发现、也最需要新机制覆盖的盲区。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-6\">六 · 对 Blackwell 部署的直接含义</h3>\n<p>把上述机制落到 B200/B300 与 GB200/GB300 NVL72 上，有三条工程判断。其一，批级随机状态与请求元数据的传递要跟 KV 复用路径解耦：前缀共享 KV 走独立缓存路径，随机状态随请求元数据走控制通路，两者在批级记录处汇合，避免缓存耦合把随机性带进奖励打分。其二，NVFP4 采样稳定性需要以固定噪声调度与批级随机状态来验证：量化会改变采样步进的数值行为，若随机状态不可复现，NVFP4 下的分布漂移就无法与量化误差区分，监控侧的随机状态命中率就成为区分两者的关键指标。其三，长尾吞吐的 SLO 判定要挂在批级屏障点上：屏障前后的批级吞吐、长尾占比与随机状态命中率三者联动，才能把“权重同步导致的停顿”与“随机性泄漏导致的漂移”分开定位。</p>\n<p>论文材料未给出数据规模、硬件档位与量化方案，因此 NVFP4 下采样稳定性与长尾吞吐的具体代价无法量化，结论外推需谨慎；也未给出消融实验，固定噪声调度与批级随机状态记录的定量贡献只能定性推断。但机制层面的判断是清楚的：旧方案把随机性折叠进实现细节，换来的是吞吐面板上的平滑和奖励信号上的不可复现；新方案把随机性显式化为请求元数据与批级状态，付出的是元数据通路、批级回写与屏障停顿的代价，换来的是奖励模型与验证器看到的样本分布可复现。对在线 RLHF 服务，后者是 SLO 的前置条件，而不是可选项。</p>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-7\">七 · 请求形态的测量口径：先把“长度分布”变成可核验的量</h3>\n<p>扩散 RLHF 的 rollout 队列不是单一分布，而是提示长度、并发与批大小三者耦合的产物。论文要求“按提示长度分桶并确定批大小”，这句话在工程上必须落成可核验的测量口径，否则分桶只是经验操作。可核验的最小口径是：对每个采样窗口记录提示 token 长度的分位点（p50/p90/p99）、桶边界、每桶批大小、桶内并发请求数与桶内批级随机状态记录条数。这四个量必须同窗口对齐，才能判断“长度分布变化”究竟改变了批构成，还是仅仅改变了排队位置。</p>\n<p>分桶的代价直接体现在显存与带宽上。前缀共享 KV 的驻留量随桶内最长前缀线性增长，而批内样本各自保留随机状态意味着每样本多一份噪声状态与步进离散化参数，这部分是常数级但不可压缩的显存开销。设桶内批大小为 <span class=\"inline-math\">B</span>、前缀长度为 <span class=\"inline-math\">L</span>、每 token KV 字节数为 <span class=\"inline-math\">k</span>，则前缀共享路径的 KV 驻留近似为 <span class=\"inline-math\">B·L·k</span> 加上随机状态开销 <span class=\"inline-math\">B·s</span>（<span class=\"inline-math\">s</span> 为单样本随机状态字节数）。分桶越细，桶内 <span class=\"inline-math\">L</span> 的方差越小、<span class=\"inline-math\">B·L·k</span> 的浪费越少，但桶数增加会抬高调度开销与批级屏障的同步频率。这是一个显存-调度权衡，而不是纯粹的吞吐优化。</p>\n<div class=\"formula\">$$\\text{KV}_{\\text{bucket}} \\approx B\\cdot L_{\\max}\\cdot k + B\\cdot s,\\qquad \\text{waste} \\propto B\\cdot (L_{\\max}-L_{\\text{mean}})$$</div>\n<p>具体例子：一个桶的边界设在 2k token，桶内实际长度分布在 800–1900 token 之间，那么按桶上界分配的 KV 驻留中有相当比例是空洞；若把桶边界改为按 p90 切分，空洞缩小但跨桶请求增多，批级屏障点也随之增多。论文没有给出长度分布数字，因此这里只能给出测量口径而非结论：分桶收益必须用“桶内长度方差 / 桶间请求迁移率”两个量同时评估。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-8\">八 · 并发与批大小：批级随机状态是并发的计量单位</h3>\n<p>并发在扩散 rollout 中不是一个标量。论文把随机种子写入请求元数据、批内样本各自维护噪声状态，这意味着并发的真实计量单位是“批级随机状态记录条数”，而不是在途 HTTP 请求数。二者在异步流水线下会分叉：请求已到达但尚未分配种子时不产生随机状态；请求已完成采样但奖励模型尚未聚合打分时，随机状态仍被批级记录持有。可核验口径应同时上报在途请求数、已分配种子的请求数、批级随机状态活跃条数，三者之差就是流水线中的“随机性滞留”。</p>\n<p>批大小对延迟的影响是非线性的，因为扩散采样是步进式的：批内每条样本要推进固定步数，批大小增大摊薄了权重读取带宽，但单批完成时间随批大小上升。设单步权重读取量为 <span class=\"inline-math\">W</span>、有效带宽为 <span class=\"inline-math\">\\(\\beta\\)</span>、步数为 <span class=\"inline-math\">T</span>，则单批计算下界近似为 <span class=\"inline-math\">\\(T·W/\\beta\\)</span>，与批大小弱相关；而奖励模型侧的分离式预填/解码按批聚合打分，其预填成本随批内总 token 数增长。因此“批大小”在 rollout 引擎与奖励模型服务两侧是两个不同的最优值，强行统一会把一侧推离 SLO。</p>\n<ul>\n<li>机制：批级随机状态随请求元数据传递，批级屏障在权重同步点丢弃跨版本状态；屏障频率与批大小共同决定有效吞吐。</li>\n<li>代价：批大小增大提升权重读取摊薄度，但抬高单批尾延迟与奖励模型预填的显存峰值；批大小减小提升屏障频率与调度开销。</li>\n<li>例子：若奖励模型服务以分离式预填接入，预填批与解码批可以不同——rollout 侧按采样步进节奏出批，奖励侧按打分聚合节奏入批，两者之间靠批级记录对齐，而不是靠相同批大小对齐。</li>\n</ul>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-9\">九 · SLO 与长尾：长尾样本的二次推理是延迟预算的隐藏项</h3>\n<p>论文明确长尾样本进入验证器二次推理，结果回写批级随机状态记录。这在 SLO 上制造了一个容易被漏算的项：长尾请求的端到端延迟等于 rollout 采样延迟加奖励模型打分延迟再加验证器二次推理延迟，而前两项的批级聚合与第三项的单样本推理节奏不同。可核验的 SLO 口径必须把长尾占比与验证器二次推理的排队深度一起上报，否则 p99 延迟的恶化会被误判为采样侧问题。</p>\n<p>长尾占比本身是负载形态的函数：提示长度分布的尾部、批内随机状态耦合导致的低奖励样本、以及跨版本屏障丢弃后重采样的样本，都会进入验证器。论文把“长尾占比”列为监控指标，但没有给出阈值。工程上可核验的做法是把长尾定义为“需要二次推理的样本数 / 批内样本总数”，并按桶记录，因为不同长度桶的长尾率不可比。</p>\n<div class=\"formula\">$$\\text{SLO}_{\\text{e2e}} = \\text{rollout}_{\\text{batch}} + \\text{reward}_{\\text{prefill+decode}} + \\mathbb{1}_{\\text{long-tail}}\\cdot \\text{verifier}_{\\text{2nd}}$$</div>\n<p>具体机制上，验证器二次推理若与奖励模型服务共享分离式预填/解码路径，会争用同一批 KV 缓存与带宽；若独立部署，则增加一份显存驻留但隔离了长尾对主路径的干扰。这是一个显存换尾延迟的决策，必须用“长尾占比 × 验证器排队深度”来定量，而不是凭经验选边。论文未给出该占比，因此这里给出的是判定框架：当长尾占比上升而主路径 p50 不变时，SLO 恶化应归因于验证器侧，而非采样随机性本身。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-10\">十 · 负载塑造方案：分桶、屏障与缓存路径的相互约束</h3>\n<p>负载形态不是被动输入，它反向约束方案的可选空间。提示长度分布决定分桶粒度，分桶粒度决定批大小，批大小决定批级屏障的频率，屏障频率又决定异步流水线能容忍多少跨版本滞留。这条链条上任何一环被负载推偏，随机性控制就会退化。论文的“固定噪声调度 + 批级随机状态记录”之所以是机制而非细节，正因为它把这条链条上的随机性从隐式变为显式：噪声调度固定后，同一提示在不同批次的采样分布差异只剩种子与步进离散化，而这两者都被记录在元数据里。</p>\n<p>前缀共享 KV 与随机性隔离的结合是另一处约束。批内样本共享前缀 KV 提升带宽利用率，但若共享缓存路径不隔离随机状态，批内样本会因缓存耦合失去独立性，奖励打分被污染。论文要求“对前缀共享的 KV 复用路径做随机性隔离”，工程含义是：共享的是前缀的键值张量，不共享的是每样本的噪声状态与步进参数。可核验口径是“随机状态命中率”——批级记录中成功匹配到当前权重版本的随机状态条数占比。该指标下降意味着屏障丢弃过多或元数据传递断裂。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>塑造的方案选择</th><th>可核验代价</th></tr></thead><tbody><tr><td>长度分布尾部厚</td><td>细分桶、按 p90 切边界</td><td>桶数上升，屏障频率上升，调度开销上升</td></tr><tr><td>并发高、批大小受限</td><td>批级随机状态条数成为并发计量</td><td>随机性滞留上升，奖励侧预填批与采样批错位</td></tr><tr><td>长尾占比高</td><td>验证器独立部署或共享预填路径</td><td>显存驻留翻倍或主路径尾延迟被争用</td></tr><tr><td>权重同步频繁</td><td>批级屏障点加密</td><td>跨版本随机状态丢弃率上升，有效吞吐下降</td></tr></tbody></table>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-11\">十一 · 方案反过来限制负载：屏障与批级记录如何压缩可调度空间</h3>\n<p>方案一旦选定，就会反过来压缩负载的可调度空间。批级屏障在权重同步点丢弃跨版本随机状态，这意味着同步点附近的在途批次不能被无限拉长：批越大，屏障等待越久，丢弃的随机状态越多。于是“批大小”不再只是吞吐参数，而是与权重同步周期绑定的约束量。设同步周期为 <span class=\"inline-math\">P</span>、单批完成时间为 <span class=\"inline-math\">\\(\\tau\\)</span>，则一个同步周期内可完成的批数约为 <span class=\"inline-math\">\\(P/\\tau\\)</span>，超出部分要么排队到下一周期，要么在屏障处被丢弃重采。这直接把负载的并发上限写成了方案的内生参数。</p>\n<p>另一个反向限制来自奖励模型与验证器的分离式接入。分离式预填/解码要求奖励侧按批聚合打分，而批级聚合的粒度受 rollout 侧出批节奏约束；若 rollout 侧因长尾而拖长出批间隔，奖励侧的预填批会变小、解码批会碎片化，带宽利用率下降。可核验的指标是“奖励侧批聚合度”——实际参与聚合的样本数 / 批级记录条数。该指标与长尾占比负相关，是判断方案是否被负载拖垮的直接证据。</p>\n<p>具体例子：当权重同步周期较短而单批完成时间较长时，批级屏障会频繁触发，随机状态命中率下降，长尾样本被反复重采，验证器二次推理队列变长，端到端 p99 被推高。此时正确的工程判断不是加大批大小，而是拉长同步周期或把屏障改为按桶触发——因为瓶颈在屏障频率而非采样吞吐。论文未给出同步周期数字，因此这里给出的是判定顺序：先看随机状态命中率，再看长尾占比，最后才动批大小。</p>\n<p>在 Blackwell 部署语境下，这套口径还需叠加量化因素：NVFP4 采样稳定性需以固定噪声调度与批级随机状态验证，而材料未给出量化方案，故不能把“随机状态命中率”直接等同于数值稳定性。可核验的做法是把随机状态命中率与批级吞吐、长尾占比三者同窗口上报，任何一项单独恶化都不足以定位失败模式——这正是论文把监控侧指标并列上报的原因。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-12\">十二 · 批级随机状态作为负载契约：分桶、屏障与长尾的代价边界</h3>\n<p>该方案的负载契约不是“请求进来就采样”，而是把随机种子写进请求元数据、把批大小绑定到提示长度分桶，再以批级屏障对齐权重版本。于是负载形态被三重约束塑形：分桶决定批内样本的前缀KV可共享程度，种子元数据决定奖励模型能否复现打分，屏障点决定异步流水线允许的并发深度。一个可核查的口径是批级有效吞吐，即单位时间内通过屏障且随机状态完整的批次数，记为 <span class=\"formula\">$$T_{\\text{batch}}=\\frac{N_{\\text{commit}}}{\\Delta t_{\\text{barrier}}}$$</span> 其中分子只计屏障后仍被奖励模型接受的批，跨版本被丢弃的批不计入。代价落在延迟上：屏障越密，off-policy 泄漏窗口越窄，但排队等待权重同步的批会拉长尾延迟；屏障越疏，吞吐上升而奖励信号跨版本漂移风险上升。失效条件是分桶粒度过粗——长短提示混批时前缀共享率下降、批内随机状态条目膨胀，元数据写入与回写验证器的开销挤占采样预算。</p>\n<p>长尾样本是这套契约最先崩的地方。长尾进入验证器二次推理，结果回写批级随机状态记录，意味着一条长尾请求要占用两次推理路径与一次跨服务回写；若验证器与rollout引擎共用分离式预填/解码的接入通道，长尾占比上升会直接抬高批级屏障的等待方差。可测口径应至少包含三项：批级吞吐、随机状态命中率（元数据中种子与批级记录可对齐的比例）、长尾占比（进入验证器二次推理的样本占批内比例）。三者共同决定SLO判定，而不是单看平均吞吐。工程判断是：随机状态命中率低于批级记录完整性的容忍线时，奖励打分已不可复现，此时提高并发只会放大漂移，正确动作是收紧分桶并前移屏障，而非加批。</p>\n<table class=\"mini\"><thead><tr><th>负载维度</th><th>方案约束</th><th>代价落点</th><th>失效条件</th></tr></thead><tbody><tr><td>输入长度分布</td><td>按提示长度分桶定批大小</td><td>前缀KV共享率、元数据体积</td><td>长短混批导致批内随机状态耦合</td></tr><tr><td>并发与批大小</td><td>批级屏障对齐权重版本</td><td>屏障等待拉长尾延迟</td><td>屏障过疏致旧版本随机状态泄漏</td></tr><tr><td>长尾占比</td><td>验证器二次推理并回写</td><td>二次推理与回写带宽</td><td>长尾抬升屏障等待方差</td></tr></tbody></table>\n<p>反向限制同样成立：方案本身在压缩负载的自由度。固定噪声调度与批级随机状态记录使同一提示在不同批次下分布可复现，但也意味着批大小不能随并发随意弹性伸缩——批一旦跨屏障重组，随机状态需重新对齐，弹性扩容的收益被元数据回写抵消。在Blackwell部署上，这条边界与NVFP4采样稳定性直接相关：量化误差会放大步进离散化带来的分布偏移，若批级随机状态未随请求元数据完整传递，NVFP4下的采样漂移无法与随机性来源区分。材料未给出硬件档位与量化方案，因此长尾吞吐与NVFP4稳定性的工程代价只能以批级吞吐、命中率、长尾占比三项口径定性核验，不能外推为具体加速比。</p>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-13\">十三 · 从采样方程到 kernel：随机性在寄存器里长什么样</h3>\n<p>论文的采样随机性不是抽象统计概念，它在 GPU 上落地为一条具体的指令序列：噪声张量的生成、噪声与 latent 的逐元素融合、以及去噪步的离散推进。把这三步映射到 Blackwell 的执行模型，才能看清随机性控制点在哪里。以一条去噪步为例，扩散采样器要完成 <span>ε_θ(x_t, t)</span> 的前向、按调度系数做 latent 更新、再叠加下一步噪声。前向的主体是 GEMM 与 attention，走 tcgen05 路径；而噪声融合是逐元素的 elementwise 操作，走 CUDA core 或向量单元。论文要求“固定噪声调度、按批记录随机状态”，工程含义就是：噪声张量必须由请求元数据里的种子确定性地生成，且生成位置与消费位置在同一 kernel 或同一可追溯的 kernel 链上，不能交给一个隐式共享的 RNG 状态。</p>\n<p>这里的第一项代价是寄存器压力与占用率。噪声张量若以 FP16 驻留，一个 batch 内每条请求的 latent 形状决定了 elementwise kernel 的向量化宽度；若为了省带宽把噪声压到 FP8，融合前必须反量化，多出一次转换。第二项代价是 kernel 启动开销：把噪声生成、融合、更新拆成三个 kernel，在小 batch、长尾请求上启动延迟占比上升；融进一个 persistent kernel 则要求随机状态在 kernel 内按请求索引可寻址。论文的批级随机状态记录，本质上就是把这个可寻址索引写进元数据，使重放时能定位到同一段 RNG 流。</p>\n<div class=\"formula\">$$x_{t-1}=\\frac{1}{\\sqrt{\\alpha_t}}\\left(x_t-\\frac{1-\\alpha_t}{\\sqrt{1-\\bar\\alpha_t}}\\,\\epsilon_\\theta(x_t,t)\\right)+\\sigma_t\\,\\xi,\\quad \\xi\\sim\\mathcal{N}(0,I)$$</div>\n<p>逐项解释：<span>α_t</span> 与 <span>\\(\\bar\\alpha_t\\)</span> 是固定噪声调度给出的标量，不随批次变化，这正是“固定噪声调度”可复现性的来源；<span>ε_θ</span> 是网络前向输出，其数值精度直接决定更新项的误差；<span>σ_t</span> 是步进离散化引入的噪声尺度，它把连续时间 SDE 离散成有限步，步数越少离散化偏差越大；<span>ξ</span> 是注入噪声，由种子决定。三类随机性在这一个式子里各占一项：<span>ξ</span> 是噪声注入，<span>σ_t</span> 与步数选择是步进离散化，而批内多条请求共享前缀 KV 时 <span>ε_θ</span> 的计算若被缓存耦合污染，就是批内耦合。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-14\">十四 · 数据类型选择：FP16/BF16 的稳定性边界与 FP8/NVFP4 的压缩代价</h3>\n<p>在 Blackwell 上做扩散 rollout，数据类型不是“越窄越快”的单调选择。BF16 与 FP16 的动态范围差异直接影响 <span>ε_θ</span> 的累加稳定性：BF16 指数位宽、尾数短，适合激活值跨度大的层，但在小量级残差上分辨率不足；FP16 尾数长、范围窄，遇到方差大的噪声张量容易在上溢边缘损失精度。论文强调奖励模型看到的样本分布要可复现，这意味着量化误差不能随批次随机漂移——同一提示在不同 batch 里若因动态范围不同触发不同的饱和路径，奖励打分就会出现系统性偏移，而这正是论文所说的“分布漂移污染奖励信号”在数值层的具体形态。</p>\n<p>FP8 与 NVFP4 把这一风险放大。FP8 的 E4M3 适合前向激活，E5M2 适合梯度类张量，但扩散采样的 latent 更新是累加型操作，窄尾数会让 <span>σ_t ξ</span> 这样的小幅噪声在多次步进后被吞掉，表现为样本多样性下降——恰好是论文关心的“批量生成样本多样性”被数值精度侵蚀。NVFP4 的块缩放（block scaling）把每若干元素共享一个缩放因子，压缩率更高，但缩放因子的选择本身引入批内耦合：同一块内不同请求的 latent 若被拼进同一缩放组，一条请求的极值会改变另一条请求的重建误差，这与论文要求“批内样本各自维护噪声状态、避免共享缓存耦合”的原则直接冲突。工程判断是：NVFP4 用于 rollout 采样时，缩放组必须按请求边界对齐，不能跨请求共享缩放因子。</p>\n<table class=\"mini\"><thead><tr><th>格式</th><th>主要风险</th><th>对随机性控制的影响</th><th>系统代价</th></tr></thead><tbody><tr><td>BF16</td><td>小量级残差分辨率不足</td><td>噪声项被截断，多样性轻微下降</td><td>带宽与 FP16 同级，无需转换</td></tr><tr><td>FP16</td><td>大方差噪声上溢</td><td>饱和路径随批次变化，分布漂移</td><td>需溢出监控，重跑代价</td></tr><tr><td>FP8</td><td>尾数窄，累加误差累积</td><td>小噪声被吞，长尾样本退化</td><td>反量化转换，额外 kernel</td></tr><tr><td>NVFP4</td><td>块缩放跨请求耦合</td><td>缩放组污染批内独立性</td><td>缩放因子元数据，对齐约束</td></tr></tbody></table>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-15\">十五 · 累加精度：TMEM 里的误差如何进入奖励打分</h3>\n<p>Blackwell 的 tcgen05 把矩阵乘的累加器放在 Tensor Memory（TMEM）中，而不是寄存器堆。这一变化对扩散采样的意义在于：<span>ε_θ</span> 的累加结果精度由 TMEM 的累加器位宽与 MMA 指令的累加模式决定，而不是由输出 dtype 单独决定。若 MMA 以 FP32 累加、再降到 BF16 输出，单步误差可控；若为了吞吐走低精度累加，误差会在去噪步之间累积，因为 <span>x_{t-1}</span> 是下一步的输入，误差递归放大。论文的批级屏障保证同一批样本看到同一版本的权重，但屏障不能消除数值误差的递归——这需要累加精度策略与噪声调度一起固定。</p>\n<div class=\"formula\">$$\\|\\delta x_T\\| \\lesssim \\sum_{t=1}^{T}\\left(\\prod_{s=t+1}^{T}\\left\\|\\frac{\\partial x_{s-1}}{\\partial x_s}\\right\\|\\right)\\|\\delta \\epsilon_t\\|$$</div>\n<p>逐项解释：<span>\\(\\delta x_T\\)</span> 是最终样本相对高精度参考的偏差；<span>\\(\\partial x_{s-1}/\\partial x_s\\)</span> 是单步去噪的雅可比，其谱范数由调度系数 <span>\\(1/\\sqrt{\\alpha_s}\\)</span> 与网络局部 Lipschitz 性质共同决定；<span>\\(\\delta \\epsilon_t\\)</span> 是第 <span>t</span> 步网络输出的数值误差，来源包括量化、累加截断与 attention 的 softmax 近似。这个式子说明：步数 <span>T</span> 越多，误差放大链越长；而 <span>\\(\\delta \\epsilon_t\\)</span> 若随批次变化（例如动态缩放因子不同），最终偏差就带上了批次相关性，奖励模型看到的分布随之漂移。工程上的控制点是固定累加模式与缩放策略，使 <span>\\(\\delta \\epsilon_t\\)</span> 成为与批次无关的确定性量。</p>\n<p>代价方面，FP32 累加占用 TMEM 容量更大，直接压缩可并发的 MMA tile 数量，进而影响单 SM 的吞吐；在 2-SM MMA 模式下，两个 SM 协同完成一个大 tile，TMEM 分配跨 SM 协调，累加精度选择还会影响配对 SM 的负载均衡。长尾请求在小 batch 下更容易暴露这一代价：tile 利用率低时，高精度累加的固定开销占比上升。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-16\">十六 · Blackwell 特性：tcgen05、TMEM、2-SM MMA 与第五代 Tensor Core 的推理含义</h3>\n<p>tcgen05 的核心是把 MMA 的发起与数据搬运解耦：异步 MMA 指令让 Tensor Core 在后台推进，SM 可以同时准备下一组操作数。对扩散采样，这意味着 <span>ε_θ</span> 的前向可以与噪声生成、上一步的 latent 更新重叠，减少步间气泡。但重叠的前提是随机状态已经按请求索引固化——若噪声生成依赖一个全局 RNG 推进顺序，异步重叠就会打乱消费顺序，破坏可复现性。论文“按批记录随机状态”的要求，在 tcgen05 异步执行模型下从“好习惯”变成“正确性前提”。</p>\n<p>TMEM 作为累加器的驻留地，使累加结果不必每步写回寄存器再读出，降低了寄存器压力，但也意味着累加精度的选择被固化在 MMA 指令里，kernel 作者需要在编译期决定。2-SM MMA 把一个大矩阵乘拆到两个 SM 上，提升了大 tile 的吞吐，代价是跨 SM 的同步与 TMEM 协调；在批内前缀共享 KV 的场景下，2-SM 配对若按 tile 而非按请求划分，同一请求的 attention 计算可能横跨两个 SM，随机状态的隔离边界就要跟着 tile 走，而不是跟着请求走——这是论文“前缀共享 KV 复用路径做随机性隔离”在硬件层的具体落点。</p>\n<p>第五代 Tensor Core 对窄精度格式的原生支持，使 FP8 与 NVFP4 的 MMA 吞吐显著高于 FP16 路径，但如前所述，窄精度带来的误差递归与缩放耦合是推理系统必须付出的稳定性代价。一个具体例子：同一提示在 batch 内与长尾请求混排时，若长尾请求触发了不同的 tile 形状与缩放组划分，其 <span>\\(\\delta \\epsilon_t\\)</span> 与短请求不同，奖励模型对两者的打分偏差就不再可比；批级随机状态记录能重放这一差异，但消除差异需要缩放组按请求对齐与固定累加模式。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-17\">十七 · 数值策略与随机性控制的联合设计</h3>\n<p>把上述机制串起来，得到一个工程判断：在 Blackwell 上做扩散 RLHF rollout，数值精度策略不能独立于随机性控制来选。固定噪声调度给出确定性的 <span>α_t</span>、<span>\\(\\bar\\alpha_t\\)</span>、<span>σ_t</span>；按请求记录种子给出确定性的 <span>ξ</span>；而 <span>ε_θ</span> 的确定性要求累加模式、缩放组边界与 tile 划分都不随批次漂移。三者缺一，奖励模型看到的分布就带批次相关性。监控侧上报的“随机状态命中率”与“长尾占比”，正是用来判定这三者是否对齐的指标：命中率下降说明种子到 kernel 的映射断了，长尾占比异常说明窄精度在长尾形状上退化。</p>\n<p>代价核算落在三处：显存上，FP32 累加与 NVFP4 缩放因子元数据同时占用 TMEM 与请求元数据空间，压缩了可并发批大小；带宽上，窄精度降低了权重与激活的搬运量，但反量化与缩放因子读取增加了额外流量；延迟上，异步 MMA 与 2-SM 协同提升了吞吐，却要求随机状态在 kernel 启动前就固化，增加了调度器的预处理步骤。论文材料未给出硬件档位与量化方案，因此这些代价的具体数值无法核验，但其结构关系是确定的：精度越窄，随机性隔离的边界就必须越细，元数据与对齐约束的开销就越高。</p>\n<p>最终落在一条可执行的机制上：rollout 引擎在分桶确定批大小之后、kernel 启动之前，把每条请求的种子、缩放组边界与累加模式写进批级元数据，作为 tcgen05 异步 MMA 的输入约束；权重同步点的批级屏障同时丢弃跨版本的随机状态与数值配置，使奖励模型与验证器看到的样本分布既在统计上可复现，也在数值上可比。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-18\">十八 · 随机状态元数据在 Blackwell 精度链路上的边界与代价</h3>\n<p>把随机种子写进请求元数据这件事，在算子层面并不免费。rollout 引擎按提示长度分桶后，批内每条请求各自维护噪声状态，而前缀共享 KV 走独立缓存路径；这意味着同一批里共享前缀的样本在 tcgen05 的 2-SM MMA 上可以合并成一次大 tile 计算，但它们的噪声状态必须逐条保留，不能随 KV tile 一起被折叠。工程上可行的做法是在批级元数据里为每条请求存一个种子与步进计数器，采样时用 <span>ξ<sub>i</sub> = f(seed<sub>i</sub>, step)</span> 逐条重放，而不是把噪声张量整体物化到显存——后者在 NVFP4 下会额外占用与激活同量级的带宽。代价是每步采样多一次轻量索引与重放，属于寄存器与指令开销，不占 HBM 带宽；收益是前缀共享路径不必为随机性隔离而放弃 tile 合并。</p>\n<p>精度边界出现在噪声与权重的数值格式不一致时。扩散采样在 FP16/BF16 下注入噪声、在 FP8 或 NVFP4 下做去噪主干计算时，噪声若以低精度累加进 TMEM，步进离散化误差会被放大：<div class=\"formula\">$$\\hat{x}_{t-1}=\\hat{x}_t-\\Delta t\\cdot\\epsilon_\\theta(\\hat{x}_t,t)+g(t)\\,\\xi,\\quad \\xi\\sim\\mathcal{N}(0,I)$$</div>其中 <span>ε<sub>θ</sub></span> 由第五代 Tensor Core 以 FP8/NVFP4 乘加、FP32 累加得到，而 <span>g(t)ξ</span> 这一项若也被压到 FP8，则 <span>g(t)</span> 较小时噪声的有效位数不足，批内样本趋于同质，奖励模型看到的分布方差被系统性低估。判断规则是：噪声注入与步进累加保持在 FP16/BF16 及以上，仅把主干卷积/注意力的乘加交给低精度 Tensor Core，累加器固定 FP32。</p>\n<table class=\"mini\"><thead><tr><th>环节</th><th>建议精度</th><th>系统代价</th></tr></thead><tbody><tr><td>噪声注入 ξ</td><td>FP16/BF16</td><td>逐条重放，指令开销，不占 HBM</td></tr><tr><td>主干乘加</td><td>FP8 / NVFP4</td><td>吞吐提升，需 FP32 累加器</td></tr><tr><td>步进累加 x</td><td>FP16 以上</td><td>TMEM 占用上升，限制 2-SM tile 尺寸</td></tr></tbody></table>\n<p>失效条件集中在批级屏障与随机状态命中率的耦合上。权重同步点做批级屏障、丢弃跨版本随机状态，能防止 off-policy 陈旧样本进入打分；但若屏障粒度过粗，长尾样本在验证器二次推理期间跨越了同步点，其回写的批级记录会与新版本策略的奖励分布错位。监控侧上报的随机状态命中率因此不是装饰指标：命中率下降意味着重放路径退化为重新采样，批级吞吐与奖励信号可复现性同时受损。在 B200/B300 档位上，这一代价体现为验证器分离式预填/解码的排队延迟，而非 Tensor Core 算力不足；NVFP4 采样稳定性在材料未给出量化方案的前提下无法核验，工程判断应是把随机状态记录与屏障点作为 SLO 的一等公民，先于量化收益评估。</p>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-19\">十九 · 显存账本的三个账户与扩散 rollout 的记账口径</h3>\n<p>在 Blackwell 上做扩散 RLHF 的 rollout，显存不是一块整账，而是三个互相挤占的账户：权重、激活、KV。权重是静态的，按 NVFP4 存储时每参数 0.5 字节，外加 per-block scale 与二级 scale 的元数据开销；激活是采样步进过程中的中间张量，随批大小与分辨率线性增长；KV 则是本片段要重点处理的部分——扩散采样的前缀共享缓存。三者共享同一 HBM3e 容量池，任何一项超配都会把另外两项挤到换页或重算路径上，直接表现为批大小被迫下调、解码步延迟抖动。</p>\n<p>记账口径必须与论文的批级随机状态对齐：批内每条请求各自持有噪声状态，但前缀 KV 是共享的。这意味着 KV 账本要按“前缀段共享、后缀段独占”来切分，而不是按请求数简单乘以单请求 KV 大小。设批内有 $B$ 条请求，共享前缀长度为 $L_p$，各自后缀长度为 $L_s^{(i)}$，每 token 每层 KV 字节数为 $b_{kv}$，层数为 $N_l$，则批级 KV 占用为：</p>\n<div class=\"formula\">$$M_{kv}=N_l\\cdot b_{kv}\\cdot\\left(L_p+\\sum_{i=1}^{B}L_s^{(i)}\\right)$$</div>\n<p>这个式子的工程含义是：前缀越长、批越大，共享项的摊薄收益越明显；但后缀段仍随批线性增长，长尾样本正是后缀段膨胀的来源。论文把长尾样本送验证器二次推理，验证器侧的 KV 账本要单独计，不能与 rollout 引擎混算，否则批级屏障点会被误判。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-20\">二十 · 分页与前缀共享：随机性隔离如何改变缓存布局</h3>\n<p>分页 KV cache 把逻辑 token 序列映射到固定大小的物理块，块表随请求元数据传递。扩散 rollout 的特殊之处在于：批内样本共享前缀 KV，但各自维护噪声状态，若共享块被某条样本的随机步进写入，就会发生批内耦合——这正是论文列为三类随机性来源之一的那一类。工程上的做法是把共享前缀块标记为只读，后缀块按请求独占分配，块表项附带随机状态标识，命中共享块时只读引用、不写回。</p>\n<p>伪代码思路如下：分配时先查前缀块表，命中则引用计数加一；未命中则新分配并写入只读标记。后缀块按请求 ID 哈希到独立页池，页池大小按批内最大后缀长度预留，避免长尾样本触发跨批换页。代价体现在两处：只读共享块使前缀段的写带宽归零，但块表查询与引用计数带来额外的元数据访存；独占后缀页池降低了页复用率，等效于 KV 容量利用率下降。对 B200 这类 HBM3e 容量有限的档位，页池预留过大会直接压缩可容纳的批大小，因此页池上限要与批级屏障点联动设定。</p>\n<p>具体例子：一个批内 8 条请求共享 512 token 前缀、各自后缀 128 到 1024 token 不等，若按最大后缀预留页池，KV 占用由共享前缀项与 8 份最大后缀项构成；若改为按实际后缀动态分配，占用下降，但长尾样本到达时可能触发页池扩容与块表重建，表现为该批尾部延迟抬升。论文的批级随机状态记录恰好提供了判断依据：监控侧上报的长尾占比决定页池预留策略。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-21\">二十一 · 压缩、复用与卸载：三条路径的带宽代价</h3>\n<p>压缩走的是 KV 量化与低秩近似，把每 token 每层字节数 $b_{kv}$ 压到 FP8 甚至 NVFP4 量级。收益是容量账本直接缩小，代价是反量化在解码路径上引入额外带宽与算力：每个解码步都要把压缩块读回并还原，HBM 读带宽的压力从“读原始 KV”转为“读压缩块加 scale 元数据”。在 Blackwell 上，tcgen05 的 MMA 吞吐远高于 HBM 带宽，因此压缩的瓶颈通常不在算力而在反量化的访存节拍，压缩比越高，元数据占比越大，边际收益递减。</p>\n<p>复用是前缀共享的延伸：跨批复用相同提示的前缀块，把块表从批级提升到会话级。复用命中率直接决定 KV 账本的有效容量，但复用路径必须与随机性隔离共存——跨批复用的前缀块若携带旧批的随机状态标识，就会把上一批的噪声耦合带进新批。论文的屏障机制在此处的落点是：权重同步点丢弃跨版本随机状态，复用块表也要按版本号失效，避免旧版本前缀块被新策略误引用。</p>\n<p>卸载把冷后缀块搬到主机内存或远端池，释放 HBM 给权重与激活。代价是 PCIe 或 fabric 往返延迟，扩散采样每步都要读全量 KV，卸载块的回归会打断步进流水，表现为解码步的周期性停顿。工程判断是：只卸载长尾样本的低命中后缀块，且卸载粒度不小于单步读取的连续段，否则往返次数吃掉全部收益。三条路径的取舍最终都落在同一个不等式上——压缩省容量但加反量化带宽，复用省容量但需版本失效管理，卸载省容量但加往返延迟，三者都不能突破 HBM3e 的容量上限。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-22\">二十二 · 带宽瓶颈定位：HBM3e 容量与带宽的复算</h3>\n<p>HBM3e 的容量按堆栈算：单堆栈容量乘以堆栈数得到单卡容量，GB200 NVL72 这类机柜级系统再把单卡容量乘以 GPU 数得到整柜池化容量。容量账本的复算顺序是：先扣权重（含 scale 元数据），再扣激活峰值，余量才是 KV 可用容量。带宽侧则要区分两个节拍：预填阶段是计算密集，KV 写入带宽与 MMA 吞吐匹配；解码阶段是访存密集，每步读全量 KV，带宽需求正比于批内活跃 token 数与层数。</p>\n<p>把解码步的 KV 读带宽写成：</p>\n<div class=\"formula\">$$BW_{kv}=N_l\\cdot b_{kv}\\cdot\\left(L_p+\\sum_{i}L_s^{(i)}\\right)\\Big/ t_{step}$$</div>\n<p>其中 $t_{step}$ 是单步目标延迟。这个式子说明：批大小提升会线性抬升带宽需求，一旦超过 HBM 有效带宽，解码步就从带宽受限转为排队受限，吞吐不再随批增长。扩散采样的步进离散化使 $t_{step}$ 有下限，固定噪声调度又要求步数不随负载压缩，因此带宽瓶颈在长尾批上最先暴露。定位方法是看批级吞吐随批大小的拐点：拐点之前是算力受限，拐点之后是带宽受限，拐点位置由 $BW_{kv}$ 与 HBM 有效带宽之比决定。</p>\n<p>具体例子：同一批内前缀共享使 $L_p$ 项被摊薄，带宽需求主要来自后缀段之和；若把长尾样本单独成批、缩短批内最大后缀差，$BW_{kv}$ 的峰值下降，但批次数增加、前缀复用率下降。这是一对矛盾，论文的按提示长度分桶正是为此：分桶把后缀长度分布压窄，使每批的带宽峰值可预测，批级屏障点也更容易卡在带宽拐点之前。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-23\">二十三 · 可复算的显存预算：从单批到整柜</h3>\n<p>给出一个可复算的预算框架，读者可代入自己档位的容量与带宽参数。第一步，权重账本：参数量乘以每参数字节数，NVFP4 下为 0.5 字节，加上 per-block scale 与二级 scale 的元数据，按块大小折算成百分比附加项。第二步，激活账本：按批大小、分辨率与采样步的中间张量峰值估算，扩散采样的激活峰值通常出现在步进中间层，需按最大批而非平均批预留。第三步，KV 账本：用第一节的公式，前缀项按共享摊薄，后缀项按批内最大后缀预留，再乘以分页块的对齐浪费系数。三步相加得到单批 HBM 占用，余量低于安全水位时下调批大小或启用压缩。</p>\n<table class=\"mini\"><thead><tr><th>账户</th><th>决定因素</th><th>工程代价</th><th>可调手段</th></tr></thead><tbody><tr><td>权重</td><td>参数量、量化格式、scale 元数据</td><td>静态占用，压缩后释放容量但加反量化</td><td>NVFP4/FP8 切换</td></tr><tr><td>激活</td><td>批大小、分辨率、步进中间张量</td><td>峰值决定批大小上限</td><td>分桶、梯度式批调度</td></tr><tr><td>KV 前缀</td><td>共享前缀长度、复用命中率</td><td>只读共享省写带宽，块表查询加元数据访存</td><td>会话级复用、版本失效</td></tr><tr><td>KV 后缀</td><td>批内最大后缀、长尾占比</td><td>独占页池降复用率，长尾触发扩容</td><td>分页、压缩、选择性卸载</td></tr></tbody></table>\n<p>整柜复算时，GB200 NVL72 的池化容量允许把 KV 账本跨 GPU 切分，但切分粒度受 NVLink 5 域内带宽约束：跨 GPU 读 KV 的延迟高于本地 HBM，解码步的带宽需求若落在跨域路径上，等效带宽下降。因此整柜预算不能简单把单卡容量相加，而要按并行拓扑把 KV 分片映射到本地域，跨域只走低频的前缀共享与卸载回归。</p>\n<p>具体例子：一个批的前缀共享项在单卡内命中，后缀项按请求独占；若把后缀分片跨两张 GPU，解码步每步都要跨域聚合，$t_{step}$ 抬升，批级吞吐的拐点前移。工程判断是：把长尾后缀留在本地域、只把共享前缀做成跨域只读副本，用 NVLink 5 的带宽换前缀复用率，而不让高频后缀走跨域路径。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-24\">二十四 · 与随机性控制的耦合点：屏障、命中率与失败模式</h3>\n<p>显存账本不是孤立的容量计算，它和论文的随机性控制在同一批级状态上耦合。批级屏障点决定了哪些随机状态可以跨批复用：屏障之前分配的 KV 块携带旧版本标识，屏障之后必须失效重建，否则 off-policy 陈旧样本的噪声会随共享块泄漏进新批打分。监控侧上报的随机状态命中率，本质上是“复用块表命中且版本一致”的比例，这个指标同时反映 KV 复用效率与随机性隔离是否失效。</p>\n<p>失败模式在显存侧的映射很直接：前缀共享块未做只读隔离，批内样本互相写入，表现为奖励打分方差异常抬升；页池按平均后缀预留而非最大后缀，长尾样本触发换页，表现为批尾延迟尖峰与吞吐拐点漂移；卸载粒度小于单步读取段，解码步往返次数上升，表现为 $t_{step}$ 周期性抖动。这三种失败都能在批级吞吐、随机状态命中率与长尾占比三项监控上定位，而这三项正是论文给出的 SLO 判定输入。</p>\n<p>工程判断落在预算的最后一格：把 KV 页池上限设为批级屏障点的函数，屏障点越密，可复用的前缀块越少，页池预留要相应放大以容纳独占后缀；屏障点越疏，复用率高但跨版本泄漏风险上升。这个取舍没有免费答案，只能按长尾占比与随机状态命中率的实测值在批调度器里动态调，而调参的边界就是 HBM3e 容量与 $BW_{kv}$ 拐点共同划定的那条线。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-25\">二十五 · 前缀共享 KV 的显存账本与随机性隔离的代价边界</h3>\n<p>这套方案在显存侧的真正约束不在权重，而在“共享前缀 KV + 批内独立随机状态”这一对必须同时成立的组合。前缀共享把同一提示的 KV 只存一份，账本按 <span class=\"formula\">$$M_{\\text{KV}}=B_{\\text{uniq}}\\cdot L_p\\cdot H_{\\text{kv}}\\cdot d_h\\cdot b_{\\text{elem}}\\cdot 2$$</span> 估算，其中 <span class=\"formula\">$$B_{\\text{uniq}}$$</span> 是去重后的前缀数而非批大小，<span class=\"formula\">$$L_p$$</span> 为前缀 token 数，因子 2 对应 K/V 两份。一旦批内样本各自保留噪声状态，前缀 KV 的物理页可以共享，但随机状态元数据必须逐请求独立分配并随批生命周期存活，等于在 KV 池之外多出一份与批大小成正比的“状态页”开销。分页机制在这里的作用是把前缀页与状态页解耦：前缀页走跨请求复用池，状态页走批内私有池，二者生命周期不同，回收时机也不同。</p>\n<p>失效条件很明确：当提示长度分布高度离散、去重率低时，<span class=\"formula\">$$B_{\\text{uniq}}$$</span> 逼近批大小，前缀共享的显存收益被稀释，而随机状态隔离的额外开销照常支付，单位 token 的 KV 成本反而高于不做隔离的朴素批处理。更关键的是，共享前缀页若在批内被多个随机状态引用，任何一次页回收都必须等所有引用方完成采样步进，否则会出现“缓存耦合”——这正是论文要求随机性隔离的原因，但代价是页回收的屏障点变多，批调度器可用的空闲页减少，长尾样本更容易触发显存不足而非算力不足。</p>\n<p>带宽侧的瓶颈随之转移。前缀共享降低了 HBM3e 上 KV 的读放大，但批级屏障与状态页的读写把压力推向请求元数据的搬运路径：每个采样步进都要校验随机状态与当前权重版本是否一致，这类校验是低算术强度的访存操作，在分离式预填/解码架构里会与奖励模型的预填争抢同一条 HBM 通道。可复算的预算应写成“前缀 KV 页 + 批内状态页 + 屏障驻留页”三项之和，并按批级屏障点数量乘以页大小估算驻留开销；若监控上报的随机状态命中率下降而长尾占比上升，说明状态页正在挤占前缀页的复用空间，此时应缩小批大小或提前切分前缀，而不是加大 KV 池。</p>\n<table class=\"mini\"><thead><tr><th>账本项</th><th>随什么增长</th><th>失效信号</th></tr></thead><tbody><tr><td>前缀 KV 页</td><td>去重前缀数 × 前缀长度</td><td>去重率低，共享收益消失</td></tr><tr><td>批内状态页</td><td>批大小 × 采样步数</td><td>命中率下降、长尾占比上升</td></tr><tr><td>屏障驻留页</td><td>权重同步点数量</td><td>回收等待拖长批尾延迟</td></tr></tbody></table>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-26\">二十六 · 连续批处理：批边界由随机状态而非请求到达决定</h3>\n<p>扩散 RLHF 的 rollout 引擎与传统自回归服务在批处理上有一个结构性差异：自回归请求的“完成”由 EOS 决定，而扩散请求的“完成”由固定步数或噪声调度终点决定。这意味着批内每条请求的剩余步数在入批时就已知，连续批处理（continuous batching）的调度器因此可以把批视为一个步数向量而非一个固定长度的矩阵。论文要求每条请求携带随机种子写入元数据，调度器在组批时必须把种子与批槽位绑定，否则同一提示在不同批中会因槽位复用而拿到不同的噪声序列。</p>\n<p>具体机制是：调度器按提示长度分桶，桶内按剩余步数排序，以“步数相同者优先同批”为组批规则，使批内样本在扩散推进中同步退出、同步补位。补位时新请求继承空出的槽位，但必须重置该槽位的随机状态，避免与前一条请求的噪声轨迹耦合。伪代码思路可写成：<code>batch = bucket(prompt_len); slot = assign(batch); slot.rng = seed(request)</code>，退出条件为 <code>step == schedule_len</code>。</p>\n<p>代价体现在吞吐与尾延迟的张力上。步数对齐的组批提高了单批的有效占空比，但长尾请求（步数多、提示长）会拖住整批的退出时间；若强行等待对齐，尾延迟被拉长；若允许批内异步退出，则槽位复用频率上升，随机状态重置开销与缓存失效次数增加。工程判断是：把步数离散化为若干档（例如按调度曲线的分段点分档），档内严格同步、档间允许抢占，用档位粒度换取尾延迟可控。在 Blackwell 上，这一步的代价直接落在 SM 占用率与 TMEM 的批内复用上——批越小，tcgen05 MMA 的 2-SM 协作越难填满，单步延迟上升。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-27\">二十七 · Chunked prefill：前缀共享 KV 与随机性隔离的交叉点</h3>\n<p>chunked prefill 在扩散 rollout 中的角色与自回归不同：扩散没有严格的“预填—解码”二分，但前缀共享 KV（同一提示的多个采样样本共享条件编码）构成了事实上的预填段。论文明确要求前缀共享 KV 走独立缓存路径，批内样本各自维护噪声状态。这带来一个调度约束：chunk 的切分点不能落在随机状态切换的边界上，否则同一 chunk 内会混入不同种子的噪声轨迹，缓存命中率与随机性隔离同时受损。</p>\n<p>机制上，调度器把前缀段按固定 token 块切分，每个 chunk 完成时写入共享缓存并标记“随机性隔离位”；后续样本引用该 chunk 时必须携带自己的种子派生偏移，而不是直接复用缓存中的噪声张量。公式上，批内第 i 条样本在第 t 步的噪声可写成 <code>ε_i,t = f(ξ_i, t)</code>，其中 ξ_i 为请求种子，共享缓存只提供条件上下文而不提供噪声。这样做的代价是缓存条目需要额外的元数据字段，显存开销随并发样本数线性增长；在 KV cache 已接近容量上限时，隔离位元数据的显存占用会挤压可并发批大小。</p>\n<p>具体例子：一个长提示被切成三个 chunk，前两个 chunk 的 KV 被 8 条采样共享，第三条 chunk 因长度不齐单独成块。若调度器把第三条 chunk 与前两条混在同一 prefill 批次，共享缓存的写入顺序会打乱随机状态的绑定顺序，奖励模型收到的样本分布出现批内漂移。工程上应把 chunk 边界与桶边界对齐，使隔离位在 chunk 粒度上稳定。吞吐代价是 chunk 越小、调度开销越高；延迟代价是 chunk 越大、首样本出结果越晚。Blackwell 上 chunked prefill 的收益主要来自减少重复前缀计算对 NVLink 带宽的占用，但隔离位元数据的读写会引入额外 HBM 往返。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-28\">二十八 · 优先级与抢占：长尾样本与权重同步屏障的冲突</h3>\n<p>论文的异步流水线在权重同步点设置批级屏障，丢弃跨版本随机状态。这条规则与优先级调度直接冲突：高优先级的长尾样本若在屏障前未完成，要么被丢弃重跑（浪费已推进的步数），要么被允许跨屏障继续（污染奖励信号）。调度器必须在屏障点前预留一个“排空窗口”，窗口内不再接纳新批，只允许已在批内的请求推进到完成或到达可抢占点。</p>\n<p>抢占的粒度应落在扩散步而非 chunk 上：扩散步之间的状态（当前噪声水平、已推进步数）可以序列化到请求元数据，恢复时从记录步继续，随机状态随元数据一同恢复。这样抢占不会破坏随机性隔离。代价是每次抢占/恢复引入一次状态序列化与反序列化的显存往返，长尾样本占比高时这部分开销会显著拉低有效吞吐。监控侧的“长尾占比”指标正是用来判断排空窗口是否够长：占比上升意味着屏障点前的等待时间变长，批级吞吐下降。</p>\n<p>具体例子：一个批次在屏障前 200ms 到达，批内 3 条长尾样本尚需 40 步。若排空窗口设为 300ms，这 3 条可完成；若设为 100ms，则必须抢占并序列化状态，恢复后重新计入下一批，奖励打分被推迟一个屏障周期。工程判断是：排空窗口应覆盖长尾样本的 P99 剩余步数时间，而不是平均值；用监控上报的长尾占比动态调整窗口长度，比固定窗口更能压住尾延迟。在 GB200 NVL72 这类多节点拓扑上，屏障还涉及跨节点权重同步的通信代价，排空窗口需与 NCCL 集合通信的完成时间对齐。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-29\">二十九 · 分离式预填/解码：奖励模型服务的接入形态</h3>\n<p>论文把奖励模型与验证器以分离式预填/解码方式接入 rollout 引擎。这里的“分离”有两层含义：计算资源分离（rollout 引擎与奖励服务不共享 SM）与调度阶段分离（预填段与解码段在不同服务实例上排队）。对扩散 RLHF 而言，奖励模型的输入是完整生成样本，因此其预填段对应样本的编码，解码段对应打分头的逐 token 或逐 patch 输出。分离式接入的好处是奖励服务的批可以独立于 rollout 批聚合，按打分吞吐而非采样步数组批。</p>\n<p>机制上，rollout 引擎在样本完成时把样本连同随机状态打包为打分请求，奖励服务按批聚合打分，批大小由打分服务的 SLO 决定而非采样批大小。公式上，批级打分吞吐可写成 <code>Throughput_r = B_r / (T_prefill + T_decode(B_r))</code>，其中 B_r 为打分批大小；B_r 增大时解码段摊薄但预填段固定开销占比下降，存在一个使吞吐最大的批大小。代价是分离式接入引入一次跨服务的样本传输，样本张量与随机状态元数据都要走网络；在 NVL72 内这走 NVLink，跨节点则走 RDMA，传输延迟直接加到端到端尾延迟上。</p>\n<p>具体例子：rollout 批完成 64 条样本，奖励服务以 32 条为一批聚合打分，两批之间插入验证器对长尾样本的二次推理。若验证器与奖励服务共享同一实例，长尾样本会阻塞正常样本的打分队列；分离部署后，验证器走独立队列，正常样本的打分尾延迟不被长尾拖累。工程判断是：验证器队列应设置独立的优先级与超时，超时样本回写批级记录并标记为“未验证”，而不是阻塞整批。Blackwell 上分离式部署的收益还体现在 NVFP4 量化的一致性上——rollout 与奖励服务可用不同的量化档位，但随机状态元数据必须跨档位保持可复现。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-30\">三十 · 尾延迟怎么压：批级记录、屏障粒度与监控闭环</h3>\n<p>尾延迟的来源在本部分可归为三类：批内步数不齐导致的退出等待、屏障点前的排空等待、跨服务传输与验证器二次推理的排队等待。论文给出的控制点是批级随机状态记录与监控上报，前者让失败可复现，后者让尾延迟可定位。压尾延迟的机制不是单一手段，而是把这三类等待分别用不同粒度约束：步数档位约束第一类，排空窗口约束第二类，验证器独立队列与超时约束第三类。</p>\n<p>监控闭环的关键指标是批级吞吐、随机状态命中率与长尾占比。随机状态命中率下降意味着槽位复用时的重置开销上升，通常伴随批内异步退出增多；长尾占比上升意味着排空窗口需要拉长或验证器队列需要扩容。这三个指标共同构成 SLO 判定的输入，而不是单独看平均吞吐。代价是监控本身要写入批级记录，每条请求的随机状态元数据在批完成时落盘或上报，带来一次额外的写放大；在高并发下这部分写带宽会与 KV cache 的读写争抢 HBM 带宽。</p>\n<p>具体例子：某批的长尾占比从基线上升到需要拉长排空窗口，调度器把窗口从覆盖 P50 改为覆盖 P99 剩余步数，批级吞吐短期下降但尾延迟分位数收敛。工程判断是：尾延迟的压制应优先保证随机状态的可复现性，再优化吞吐；因为不可复现的样本分布会让奖励信号漂移，后续策略更新的代价远高于一次排空窗口的吞吐损失。在 B200/B300 档位上，这意味着调度器的参数应以批级记录为反馈信号做闭环调整，而不是按静态配置运行。</p>\n<p>最后落在具体机制上：调度器的组批规则应把“随机种子绑定槽位”作为硬约束，把“步数档位对齐”作为软约束，把“排空窗口覆盖 P99”作为屏障点的默认策略；三者共同决定批级吞吐与尾延迟的取舍点，而监控上报的随机状态命中率是判断该取舍点是否漂移的唯一依据。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-31\">三十一 · 随机状态与批级屏障：调度边界、失效条件与系统代价</h3>\n<p>把随机种子写进请求元数据只是第一步，真正的工程难点在于调度器如何对待这份元数据。连续批处理在解码侧按 token 迭代拼批，chunked prefill 把长提示切段塞进空闲算力，两者都会让同一条请求跨越多个批、多个版本。论文要求批内样本共享前缀 KV 却各自保留随机状态，这意味着调度器必须把“批”同时当作随机性隔离单元：一旦某条请求被抢占、重排或跨权重版本续跑，其元数据中的种子与噪声调度位置必须能独立重放，否则前缀缓存命中带来的收益会被分布漂移抵消。一个具体机制是：在 rollout 引擎的批描述符里附带随机状态版本号，抢占时把该状态随 KV 块一起换出，续跑时校验版本号一致才允许复用缓存。</p>\n<div class=\"formula\">$$T_{\\text{batch}}=\\max_{i\\in B}\\left(T_{\\text{prefill},i}+T_{\\text{decode},i}\\right)+\\sum_{k}T_{\\text{barrier},k},\\quad \\text{s.t. } \\text{ver}(\\xi_i)=\\text{ver}(\\theta)$$</div>\n<p>这条式子给出的是批级屏障的代价结构：批完成时间由最慢成员决定，屏障点还要叠加同步开销，约束则是每条请求的随机状态版本必须与当前策略版本一致。尾延迟正来自这两项——长尾样本在验证器二次推理中拉长 max 项，跨版本屏障则把异步流水线的重叠窗口压窄。失效条件很明确：当长尾占比升高、批内长度方差变大时，分桶策略失效，短请求被长请求拖住；当权重同步频繁而屏障粒度过粗时，丢弃跨版本随机状态会让大量在途请求重算，吞吐骤降。分离式预填/解码能缓解这一点，把预填与解码放在不同资源池，但随机状态仍需随请求迁移，迁移路径上的序列化与校验就是新增带宽与显存开销。</p>\n<table class=\"mini\"><thead><tr><th>调度动作</th><th>随机性风险</th><th>系统代价</th></tr></thead><tbody><tr><td>前缀 KV 共享</td><td>批内耦合，样本失去独立性</td><td>需按请求隔离噪声状态，缓存元数据膨胀</td></tr><tr><td>抢占与重排</td><td>跨批续跑时种子错位</td><td>状态换出/换入，尾延迟抬升</td></tr><tr><td>权重同步屏障</td><td>旧版本随机状态泄漏</td><td>在途请求重算，吞吐短时下降</td></tr></tbody></table>\n<p>工程判断落在粒度选择上：屏障应按批而非按请求设置，把随机状态命中率与长尾占比作为 SLO 判定指标上报，用命中率下降预警缓存耦合，用长尾占比预警验证器侧的二次推理压力。Blackwell 部署下，NVFP4 采样路径的数值稳定性尚未被材料量化，因此固定噪声调度与批级状态记录应作为默认可复现基线，而不是可选项；任何试图靠共享缓存提升吞吐的调度改动，都必须先证明它没有改变奖励模型看到的输入分布。</p>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-32\">三十二 · 并行拓扑与随机状态的可复现边界</h3>\n<p>在 Blackwell 上谈并行，先要回答一个比“切几路”更前置的问题：切分之后，随机状态还属于谁。论文把扩散采样随机性拆成噪声注入、步进离散化与批内耦合三类，并要求随机种子随请求元数据传递。这条要求在 TP/EP/PP/DP 四种切分下含义完全不同。数据并行（DP）是最“干净”的一档：每张卡持有完整权重、独立跑自己的批，随机种子天然按请求归属，只要批级屏障对齐权重版本即可。张量并行（TP）把同一层的权重矩阵按列或按行切开，一次前向里所有 rank 必须参与同一组集合通信，此时“批内样本各自维护噪声状态”仍成立，因为噪声是逐样本、逐 step 的标量或张量，不随权重切分而分裂；但一旦某个 rank 因负载不均提前进入下一步，集合通信就会把整个 TP 组拖到最慢者的节奏上，随机步进的时序被打乱。流水并行（PP）更微妙：micro-batch 在 stage 间流动，随机状态必须跟着 micro-batch 走，而不能留在某个 stage 的本地缓存里。专家并行（EP）在 MoE 结构下引入 All-to-All，token 被路由到不同专家，随机状态若只按“批”记录而不按“token 路由结果”记录，就会出现同一批内不同 token 看到不同版本缓存的情况。</p>\n<p>论文的批级随机状态记录，落到工程上就是一条元数据契约：请求 ID、随机种子、噪声调度版本、前缀 KV 缓存键、权重版本号，五者绑定。任何一次集合通信前后，这五项必须原子地随数据流动。代价是显存的元数据开销与调度器的记账开销——每条请求几十字节量级，但在万级并发下会挤占调度器的 CPU 侧预算，表现为批形成延迟上升。具体例子：一个按提示长度分桶的 rollout 队列，短桶批大小大、长桶批大小小，若短桶请求在 TP 组内与长桶请求混跑，TP 组会被长桶的慢 rank 拖住，短桶的随机步进被迫等待，批级吞吐下降而随机状态命中率不受影响——这正是监控侧需要把“批级吞吐”和“随机状态命中率”分开上报的原因。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-33\">三十三 · NVLink 5 与 NVSwitch：集合通信的物理下限</h3>\n<p>Blackwell 世代的 GB200/GB300 NVL72 把 72 颗 GPU 放进一个 NVLink 域，NVLink 5 与 NVSwitch 提供域内全互联。这条事实的工程含义是：TP 与 EP 的集合通信在域内不再经过 InfiniBand，All-Reduce 与 All-to-All 的带宽上限由 NVLink 与 NVSwitch 决定，而不是网卡。对推理而言，这意味着 TP 组的规模可以更大而不至于被互联带宽掐死，但“更大”不等于“更快”——集合通信的延迟随参与 rank 数增长，All-Reduce 的环状或树状实现里，跳数与同步点数量都在增加。</p>\n<div class=\"formula\">$$T_{\\text{comm}} \\approx \\alpha \\cdot \\log_2 N + \\beta \\cdot \\frac{S}{B_{\\text{NVLink}}}$$</div>\n<p>式中 α 是单次同步的固定延迟，N 为参与 rank 数，S 为单次传输字节数，β 为与实现相关的系数，B 为链路带宽。这个式子说明两件事：小消息被 α 主导，大消息被带宽主导。扩散采样的一次前向里，TP 的 All-Reduce 发生在每个去噪 step 的注意力与 MLP 之后，消息尺寸随 hidden 维与批大小变化；步数多、单步消息小，于是 α 项累积成主要成本。一个具体例子：固定噪声调度下每步都要做一次 TP All-Reduce，若把 TP 从 2 扩到 8，单步同步点从 1 次变成 3 次（log₂8），延迟项近似翻三倍，而单步计算量只降到八分之一——在批大小不足以填满计算单元时，通信反而成为主导。这就是“通信什么时候成为瓶颈”的第一条判据：当单步计算时间与 α·log₂N 同量级时，扩 TP 是负收益。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-34\">三十四 · All-to-All 与 EP：路由带来的非对称流量</h3>\n<p>EP 下的 All-to-All 与 TP 的 All-Reduce 有本质区别：All-Reduce 是规约，流量对称；All-to-All 是分发，流量取决于路由结果。MoE 推理里 token 到专家的分配天然不均衡，热门专家收到的 token 多，冷门专家少，于是 All-to-All 的每个 rank 发送与接收字节数不等，最忙的链路决定整体时延。这与论文的“批内耦合”问题是同构的：批内样本共享前缀 KV 但各自保留随机状态，若共享缓存的访问模式让某些样本的 KV 命中率远高于其他样本，批内推进速度就会分化，慢样本拖住整批。工程上的对策是把路由结果与随机状态一起写进批级记录，让调度器能识别“这一批的随机状态是否因路由不均而失真”。</p>\n<p>代价体现在三个维度：带宽上，All-to-All 的有效利用率受最忙链路限制，实际可达带宽低于 NVLink 峰值；显存上，EP 要求每个 rank 持有部分专家权重，专家副本的放置策略影响显存均衡；延迟上，All-to-All 的完成依赖所有 rank 的发送与接收配对，任一 rank 的调度抖动都会放大。具体例子：一个长尾样本进入验证器二次推理时，若它被路由到冷门专家，该 rank 的 All-to-All 接收量小、发送量也小，看似轻松，但它必须等待热门 rank 完成分发才能进入下一步——长尾样本的时延由最忙 rank 决定，而非由自身计算量决定。监控侧的“长尾占比”指标若不与路由分布联合分析，就无法定位这类等待。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-35\">三十五 · NIXL 传输与分离式预填/解码的通信账</h3>\n<p>论文把奖励模型与验证器以分离式预填/解码方式接入，异步流水线在权重同步点做批级屏障。分离式部署的通信账不在计算侧，而在 KV 与样本的搬运侧。NIXL 作为传输层的作用是把 KV 缓存与请求元数据在预填节点与解码节点之间搬移，其代价由传输字节数与传输次数共同决定。扩散采样的样本是完整生成结果，送入奖励模型服务时是整段序列而非增量 token，因此传输是批量、单向、大块的，与自回归解码的逐 token 搬运形态不同。</p>\n<div class=\"formula\">$$T_{\\text{xfer}} = \\frac{S_{\\text{KV}} + S_{\\text{meta}}}{B_{\\text{xfer}}} + n_{\\text{hops}} \\cdot \\alpha_{\\text{xfer}}$$</div>\n<p>这里 S_KV 是前缀共享 KV 的字节数，S_meta 是随机状态与批级记录的元数据，n_hops 是跨节点跳数。论文要求随机状态随请求元数据传递，意味着元数据虽小但必须与 KV 同批到达，否则奖励模型看到的样本分布不可复现。工程判断是：当 KV 复用率高、前缀共享路径独立缓存时，S_KV 的传输可被摊薄；但当批级屏障触发、跨版本随机状态被丢弃时，被丢弃的那部分 KV 与元数据就是纯浪费的传输量。具体例子：权重同步点到来时，异步流水线里尚有未完成打分的批次，屏障要求丢弃其随机状态，这些批次的 KV 已传输但不再可用，传输带宽被消耗在一次性的、不可复用的搬运上——这是分离式部署在权重同步频率高时的隐性成本。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-36\">三十六 · 通信成为瓶颈的判据与批级屏障的取舍</h3>\n<p>把上述几条收拢成可操作的判据。第一条：单步计算时间 T_comp 与集合通信延迟 T_comm 的比值。当 T_comm/T_comp 超过某个由 SLO 决定的阈值时，扩并行度不再降低端到端时延，反而因同步点增多而抬高尾延迟。第二条：All-to-All 的最忙链路利用率。当路由不均导致最忙链路接近饱和而平均利用率低时，瓶颈在路由而非带宽，此时应调整专家放置或批内 token 分布，而非加链路。第三条：分离式传输的有效载荷率。当批级屏障丢弃的随机状态占比升高时，传输带宽被浪费，应降低权重同步频率或把屏障点与批边界对齐。</p>\n<p>论文的批级屏障是一个明确的工程取舍：它用“丢弃跨版本随机状态”换取“奖励模型看到的分布与当前策略一致”。代价是屏障点前后的批次吞吐出现凹口，凹口深度取决于屏障时未完成批次的数量。监控侧上报的批级吞吐与随机状态命中率正是用来量化这个凹口的。具体例子：若屏障点设在批边界而非任意时刻，未完成批次为零，凹口消失，但权重同步的等待时间变长；若设在批中间，吞吐凹口出现，但权重更新更及时。这个取舍没有普适答案，取决于 SLO 是偏向吞吐还是偏向策略新鲜度。对 Blackwell 部署而言，NVFP4 采样稳定性尚未量化，固定噪声调度与批级随机状态记录是当前唯一可复现的控制点，通信侧的屏障设计必须与之对齐，否则量化误差与随机性漂移会叠加，使奖励信号的可复现性失去意义。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-37\">三十七 · 随机性屏障落进并行拓扑之后：边界、失效与代价</h3>\n<p>论文的批级屏障与随机状态元数据在单机单卡上只是簿记开销，一旦映射到 TP/EP/PP/DP 切分，它就变成一条横跨通信域的同步语义。DP 副本各自持有独立的随机种子序列，屏障点必须落在权重同步的 All-Reduce 之后、下一批 rollout 之前；TP 组内前缀共享 KV 被切分到多个 rank，若随机状态只挂在请求元数据上而不随 KV 分片一起广播，同一前缀的不同分片会读到不一致的噪声调度，批内耦合重新出现。EP 场景更尖锐：专家并行下 All-to-All 的完成时刻决定 token 何时进入下一层，扩散采样若在 All-to-All 未收敛时推进步进，步进离散化误差会与路由抖动叠加，奖励模型看到的分布偏离当前策略。PP 的微批流水则让屏障点天然错位——stage 0 的随机状态与 stage k 的权重版本可能相差一个微批，批级屏障必须按微批编号而非按批编号对齐，否则跨版本泄漏从批间转移到 stage 间。</p>\n<p>通信何时成为瓶颈可以用一个判据表达。设单批 rollout 的计算时间为 <span class=\"inline-math\">T<sub>comp</sub></span>，一次屏障涉及的集合通信量为 <span class=\"inline-math\">V</span>（权重分片加随机状态元数据），有效带宽为 <span class=\"inline-math\">B<sub>eff</sub></span>，则屏障开销占比为</p>\n<div class=\"formula\">$$\\eta=\\frac{V/B_{\\text{eff}}}{T_{\\text{comp}}+V/B_{\\text{eff}}},\\qquad \\text{瓶颈判据：}\\ \\eta&gt;\\eta_{\\text{SLO}}$$</div>\n<p>NVLink 5 与 NVSwitch 把单跳带宽抬到域内不再是瓶颈的量级，但 <span class=\"inline-math\">B<sub>eff</sub></span> 取决于拓扑：跨 NVL72 机柜的流量要经过交换机与 NCCL 的 ring/tree 选择，EP 的 All-to-All 在专家数增大时呈二次增长，PP 的 stage 间点对点传输受微批深度约束。真正决定 <span class=\"inline-math\">η</span> 的是 <span class=\"inline-math\">V</span> 里随机状态元数据的占比——种子、噪声调度版本、批级记录若按请求逐条传输，元数据量会随并发线性膨胀，在小 batch、长尾占比高的负载下反而压过权重同步本身。NIXL 的点对点传输适合把验证器的长尾二次推理与 rollout 引擎解耦，但它不解决屏障语义：NIXL 只保证数据搬运完成，批级屏障仍需在控制面上显式对齐版本号。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>触发拓扑</th><th>系统代价</th></tr></thead><tbody><tr><td>随机状态未随 KV 分片广播</td><td>TP 组内前缀共享</td><td>批内样本失去独立性，奖励打分方差上升，需重跑批次</td></tr><tr><td>All-to-All 未收敛即推进步进</td><td>EP 大专家数</td><td>路由抖动叠加离散化误差，长尾样本命中率下降</td></tr><tr><td>屏障按批而非按微批对齐</td><td>PP 深流水</td><td>stage 间版本错位，off-policy 样本进入打分</td></tr><tr><td>元数据逐请求传输</td><td>DP 高并发小 batch</td><td>η 超阈值，屏障等待吞掉 rollout 吞吐</td></tr></tbody></table>\n<p>工程判断落在两处：其一，把随机状态压缩为批级摘要而非逐请求明细，只在验证器回写长尾记录时展开，使 <span class=\"inline-math\">V</span> 与批大小解耦；其二，屏障点按微批编号对齐 PP 流水，并在 EP 的 All-to-All 完成事件上挂接步进门控，而不是依赖固定时间窗。材料未给出硬件档位与量化方案，NVFP4 下噪声调度与路由抖动的耦合无法量化，因此上述判据只能作为拓扑选型与 SLO 设定的定性边界——当 <span class=\"inline-math\">η</span> 逼近阈值时，优先缩批而非加卡，因为加卡会同时抬高 <span class=\"inline-math\">V</span> 与 All-to-All 的通信阶数。</p>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-38\">三十八 · 精度塌陷：从随机状态漂移到奖励信号失真</h3>\n<p>在扩散RLHF的rollout链路上，“精度塌陷”不是指权重数值溢出，而是指采样分布的可复现性被破坏后，奖励模型看到的输入分布与当前策略实际生成的分布发生系统性偏离。论文把随机性拆为噪声注入、步进离散化与批内耦合三类来源，其中任何一类在批级未被记录，都会让同一提示在不同批次、不同随机种子下产生分布漂移。漂移一旦进入奖励打分，策略更新就会沿着被污染的梯度方向走，表现为奖励均值看似平稳、但方差逐批放大，最终在验证器二次推理的长尾样本上暴露为打分不可信。</p>\n<p>定位这类问题的核心手段是把随机状态当作请求元数据的一部分做可复现校验。对每条请求记录种子与噪声调度标识，重放同一批次的子集，比较奖励分数的批内离散度：</p>\n<div class=\"formula\">$$\\Delta_b=\\frac{1}{|B|}\\sum_{i\\in B}\\left|r_\\phi(x_i;\\xi_i)-r_\\phi(x_i;\\xi_i')\\right|$$</div>\n<p>当 $$\\Delta_b$$ 在固定噪声调度下应趋近于零（同一随机状态重放），若显著非零则说明前缀共享KV路径发生了随机性耦合——批内样本共享缓存却未隔离噪声状态，导致样本失去独立性。工程代价上，这种塌陷不增加显存也不报错，但会让奖励模型服务的打分吞吐“看起来正常”而策略质量静默下滑；在Blackwell部署中，若NVFP4采样路径未固定噪声调度，量化误差与随机性耦合叠加会放大 $$\\Delta_b$$，因此监控侧必须把随机状态命中率与批级吞吐并列上报，而不是只看吞吐。</p>\n<ul>\n<li>机制：请求元数据携带种子与调度标识，批级记录随机状态；重放子集做 $$\\Delta_b$$ 校验。</li>\n<li>代价：静默降级不触发OOM也不触发超时，只体现在奖励方差与长尾占比上。</li>\n<li>例子：同一提示在相邻两批中奖励分差超过批内正常离散度，追溯发现前缀KV复用未隔离噪声状态。</li>\n</ul>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-39\">三十九 · OOM与批抖动：批大小、KV复用与屏障点的耦合</h3>\n<p>OOM在rollout引擎里往往不是单点显存不足，而是批抖动的前兆。论文的调度方式是按提示长度分桶并确定批大小，批内样本共享前缀KV但各自保留随机状态。前缀共享节省了KV显存，却让批大小对长度分布高度敏感：长尾提示进入同一桶时，前缀KV的复用率下降、独立缓存路径增多，显存占用在批次间跳动。若异步流水线在权重同步点缺少批级屏障，旧版本的随机状态与缓存布局会跨版本泄漏，新批次可能继承上一版本的KV碎片，表现为批大小被迫下调、吞吐锯齿状波动。</p>\n<p>诊断批抖动的做法是把批级吞吐、随机状态命中率与长尾占比三条曲线对齐看。命中率下降伴随长尾占比上升，说明前缀共享路径被长尾样本打断；此时若强行维持批大小，显存峰值会逼近上限并触发OOM。控制手段是在rollout队列中按SLO设定批级屏障点，屏障处丢弃跨版本随机状态并重置缓存布局，代价是屏障点引入一次流水线停顿，吞吐短时下探，但换来了批大小的可预测性。</p>\n<table class=\"mini\"><thead><tr><th>观测信号</th><th>指向的失败模式</th><th>工程动作</th></tr></thead><tbody><tr><td>随机状态命中率下降 + 长尾占比上升</td><td>前缀KV复用被打断，批抖动</td><td>按长度重分桶，屏障点重置缓存</td></tr><tr><td>批大小被迫下调、吞吐锯齿</td><td>跨版本KV碎片泄漏</td><td>权重同步点加批级屏障</td></tr><tr><td>显存峰值贴近上限但无报错</td><td>OOM前兆，静默降级</td><td>降低并发，隔离长尾桶</td></tr></tbody></table>\n<p>具体例子：一个按提示长度分桶的批次在长尾样本涌入后，前缀共享KV的复用路径被拆成多条独立缓存，显存占用跳升，引擎自动缩小下一批批大小，吞吐出现周期性凹陷；对齐三条曲线后确认是屏障点缺失导致旧版本缓存未释放。代价是屏障停顿占用的流水线时间，收益是OOM从随机事件变成可预测的容量规划输入。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-40\">四十 · 尾延迟：长尾样本与验证器二次推理的放大效应</h3>\n<p>尾延迟的来源在论文结构里很明确：长尾样本进入验证器二次推理，结果回写批级随机状态记录。验证器以分离式预填/解码方式接入，二次推理意味着同一批内大部分样本在奖励模型服务完成打分后即可释放，而少数长尾样本要继续占用验证器资源。若批级屏障点设置不当，长尾样本会拖住整个批次的完成判定，P99延迟被少数样本拉长，而P50看起来正常——这正是尾延迟最难定位的形态。</p>\n<p>定位方法是按批统计长尾占比与验证器排队深度，把尾延迟分解为“奖励模型打分时间”与“验证器二次推理时间”两段。若后者占比随长尾占比线性上升，说明验证器侧的分离式预填/解码没有按批聚合，长尾样本各自触发独立预填，放大了尾延迟。控制手段是把长尾样本单独成桶、在屏障点之后异步提交验证器，代价是这部分样本的奖励信号回写延迟增加，但不再阻塞主批的SLO判定。</p>\n<ul>\n<li>机制：长尾样本二次推理回写批级记录，分离式预填/解码按批聚合打分。</li>\n<li>公式思路：$$T_{99}=T_{rm}+T_{ver}\\cdot\\frac{n_{tail}}{|B|}$$，尾延迟随长尾占比放大。</li>\n<li>代价：验证器资源占用与回写延迟，收益是主批P99不被长尾拖垮。</li>\n<li>例子：一批内长尾占比上升后P99跳升而P50不变，分解后发现验证器预填未聚合。</li>\n</ul>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-41\">四十一 · 静默降级：监控指标的选择与误判</h3>\n<p>静默降级是本部分最需要工程判断的失败模式：系统不报错、不OOM、不超时，但奖励信号已经不可复现。论文监控侧上报批级吞吐、随机状态命中率与长尾占比，这三项正是识别静默降级的抓手。只盯吞吐会误判——吞吐稳定可能掩盖随机状态命中率下降，因为前缀共享KV仍在工作，只是随机性隔离失效，批内样本失去独立性，奖励打分方差悄悄变大。</p>\n<p>诊断顺序应是先看随机状态命中率，再看长尾占比，最后看吞吐。命中率是随机状态随请求元数据传递并成功回写的比例，它下降意味着批级记录不完整，重放校验 $$\\Delta_b$$ 会失败；长尾占比上升意味着验证器二次推理负载增加，尾延迟与打分延迟同时恶化。三者联动才能区分“容量不足”与“随机性控制失效”。在Blackwell部署上，NVFP4采样稳定性未在材料中量化，因此命中率与 $$\\Delta_b$$ 应作为量化方案变更后的必检项，而不是等吞吐下降才排查。</p>\n<table class=\"mini\"><thead><tr><th>指标</th><th>正常形态</th><th>静默降级形态</th></tr></thead><tbody><tr><td>批级吞吐</td><td>随批大小平稳</td><td>平稳但奖励方差上升</td></tr><tr><td>随机状态命中率</td><td>接近全量回写</td><td>逐批下滑，重放失败</td></tr><tr><td>长尾占比</td><td>按长度分布稳定</td><td>上升并拖长验证器队列</td></tr></tbody></table>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-42\">四十二 · 定位与回滚：屏障点作为可回滚的控制面</h3>\n<p>定位的落点是批级屏障。论文在异步流水线的权重同步点设置批级屏障，丢弃跨版本随机状态，防止off-policy陈旧样本进入打分。这个屏障同时是回滚的控制面：当监控发现命中率下滑或 $$\\Delta_b$$ 超阈值，回滚动作不是回退模型权重，而是回退到上一个屏障点的批级随机状态记录，重放该批次并重新打分，确认分布与当前策略一致后再放行后续批次。回滚的代价是一次批级重放占用的rollout与奖励模型算力，收益是把污染范围限制在单个屏障区间内，而不是让漂移跨版本累积。</p>\n<p>工程判断上，屏障点密度需要与SLO绑定：屏障过密，流水线停顿频繁、吞吐下探；屏障过疏，跨版本随机状态泄漏窗口变大、回滚重放成本上升。论文未给出批大小与并发数字，因此屏障点应按批级吞吐与随机状态命中率的联动曲线来定，而不是照搬固定间隔。具体例子：命中率连续下滑后触发回滚，重放上一屏障区间发现前缀KV复用路径未隔离噪声状态，修复后命中率恢复，长尾占比回落，尾延迟随之收敛——这条链路说明失败模式诊断必须把随机状态记录、屏障点与监控指标当作一个闭环，而不是三个独立工具。</p>\n<ul>\n<li>机制：权重同步点批级屏障丢弃跨版本随机状态，回滚以屏障区间为单位重放。</li>\n<li>代价：重放算力与屏障停顿，收益是污染范围可控、SLO判定可复现。</li>\n<li>例子：命中率下滑触发回滚，重放定位到KV复用未隔离，修复后尾延迟收敛。</li>\n</ul>\n<p>把这三类来源的批级记录与屏障点对齐之后，失败模式就不再是“随机出现的坏批次”，而是可被命中率、长尾占比与 $$\\Delta_b$$ 三条曲线联合定位的确定性事件；NVFP4采样稳定性虽未量化，但固定噪声调度与批级随机状态记录提供了变更后可复验的最小控制点。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-43\">四十三 · 批级屏障失效与随机状态泄漏的定位路径</h3>\n<p>该方案最脆弱的边界不在采样器本身，而在权重同步点那道批级屏障。屏障一旦被异步流水线的调度抖动绕过，旧版本的随机状态就会随请求元数据进入新策略的奖励打分，形成跨版本泄漏；此时奖励信号并不报错，只是分布悄悄偏移。定位手段是把屏障点当作可观测事件：每条请求元数据携带随机种子与版本号，奖励模型服务在打分前比对版本号与当前批级记录，不一致即计入“跨版本命中”。监控侧上报的随机状态命中率一旦偏离基线，就说明屏障没有真正闭合，而不是采样噪声变大。代价是显性的：屏障强制整批等待，rollout队列的批级吞吐在同步点出现周期性凹陷，长尾样本越多的批次凹陷越深，SLO 上的表现是尾延迟抬升而非均值恶化。</p>\n<p>第二类失效是前缀共享KV未做随机性隔离。批内样本共享前缀缓存本是为省显存与带宽，但若缓存路径同时承载噪声状态，批内样本就会因缓存耦合失去独立性，奖励模型看到的样本相关性被抬高，打分方差被压低。诊断方式是在批级记录中比对“共享前缀样本的奖励方差”与“独立路径样本的奖励方差”，前者显著收缩即为耦合信号。工程代价体现在显存与带宽的取舍上：隔离随机状态意味着前缀缓存不能整块复用，KV 复用率下降，解码阶段的显存带宽压力上升；在 Blackwell 上这条路径还要与 NVFP4 采样的数值稳定性一起看，量化误差与缓存耦合叠加时，分布漂移更难归因。</p>\n<p>第三类是精度塌陷与静默降级，二者都不抛异常。精度塌陷表现为固定噪声调度下同一提示跨批次生成分布的漂移超出记录范围，可用批级随机状态回放做差分：同一随机种子重放，若奖励分不一致，则问题在数值路径而非采样逻辑。静默降级则是监控指标本身失真——随机状态命中率与长尾占比上报正常，但验证器二次推理的样本已被批调度丢弃。判据可写成批级一致性检查：</p>\n<div class=\"formula\">$$\\text{drift}_b=\\big|\\,\\mathbb{E}[r_\\phi(x)\\mid \\xi_b]-r_{\\text{ref}}\\,\\big|&gt;\\tau \\;\\Rightarrow\\; \\text{回滚至上一屏障版本}$$</div>\n<p>其中 $\\xi_b$ 为批级随机状态记录，$r_{\\text{ref}}$ 为固定种子重放的参考分。回滚不是重跑整个批次，而是丢弃跨版本随机状态、以屏障点前的批级记录重建打分队列，代价是一次批级重算的吞吐损失与验证器二次推理的排队延迟；若不回滚，污染会沿异步流水线向后传播，长尾样本吞吐的评估彻底失去基准。</p>\n<table class=\"mini\"><thead><tr><th>失效模式</th><th>可观测信号</th><th>系统代价</th></tr></thead><tbody><tr><td>屏障未闭合</td><td>跨版本命中率上升、尾延迟抬升</td><td>批级吞吐周期性凹陷</td></tr><tr><td>KV 随机性耦合</td><td>批内奖励方差收缩</td><td>KV 复用率下降、显存带宽上升</td></tr><tr><td>精度塌陷</td><td>同种子重放奖励分不一致</td><td>批级重算与验证器排队</td></tr></tbody></table>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-44\">四十四 · 基准口径的三层结构：论文没给的，部署必须自己定</h3>\n<p>这篇论文的评测口径有一个必须首先讲清的事实：材料未给出数据规模、硬件档位与量化方案，也未给出可核验的吞吐数字。因此任何“该方案在 B200 上提升多少”的说法都不成立。工程读者要做的是把基准拆成三层，逐层标注哪些是论文给定的、哪些是部署方必须自证的。</p>\n<p>第一层是<b>语义层</b>：随机种子写入请求元数据、批内样本各自保留噪声状态、权重同步点做批级屏障。这三条是论文的机制主张，与硬件无关，可直接作为验收项。第二层是<b>口径层</b>：批大小、并发、提示长度分桶、长尾占比，论文只说明“按提示长度分桶并确定批大小”，未给数值，部署时必须自行固定并写入报告。第三层是<b>硬件层</b>：SM100/SM103 档位、NVFP4 或 FP8 采样路径、并行拓扑，论文完全未涉及，属于外推区。</p>\n<p>三层不可混读。语义层的结论可以跨硬件迁移；口径层的数字只在同一分桶策略下可比；硬件层的任何数字都必须附带档位与量化方案，否则不可比。一个具体的判据是：报告里若出现“吞吐提升 X%”却未同时给出批大小、并发上限、提示长度分布与精度路径，该数字应直接作废。</p>\n<div class=\"formula\">$$\\text{可比性}=\\mathbf{1}[\\text{分桶策略同}]\\cdot\\mathbf{1}[\\text{批与并发同}]\\cdot\\mathbf{1}[\\text{精度路径同}]\\cdot\\mathbf{1}[\\text{屏障点同}]$$</div>\n<p>代价上，这套三层口径本身有工程开销：批级随机状态记录意味着每条请求多一份元数据（种子、噪声调度版本、批内序号），在万级并发下元数据的显存与带宽占用不可忽略；批级屏障则会在权重同步点引入一次全局停顿，直接体现在 TPOT 的尾部分布上。这两项代价在论文中未被量化，部署方必须自己测。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-45\">四十五 · 硬件档位与精度路径：外推区的边界在哪</h3>\n<p>论文的机制主张里，唯一与数值精度直接相关的是“固定噪声调度”。扩散采样在 NVFP4 下推进时，噪声注入的量化误差会与步进离散化误差叠加，改变批内样本的分布。论文没有给出量化方案，所以“NVFP4 下采样稳定性”属于未核验项，不能引用为结论。</p>\n<p>工程上应把档位差异写成可执行的对照表，而不是笼统的“Blackwell 加速”。B200/B300 单机与 GB200/GB300 NVL72 机柜的差别不在算力峰值，而在<b>批级屏障的代价结构</b>：单机内屏障走 NVLink 域内同步，代价是微秒级；跨 NVL72 的批级屏障涉及多节点集合通信，屏障点若落在权重同步处，会把一次 rollout 批的尾部延迟拉长到与通信拓扑同阶。这意味着同一套“权重同步点做批级屏障”的机制，在两种档位下的 SLO 表现完全不同。</p>\n<table class=\"mini\"><thead><tr><th>口径项</th><th>论文给定</th><th>部署需自证</th><th>不可比风险</th></tr></thead><tbody><tr><td>随机种子记录</td><td>是（元数据）</td><td>元数据开销</td><td>低</td></tr><tr><td>批大小/并发</td><td>否</td><td>分桶后固定</td><td>高</td></tr><tr><td>精度路径</td><td>否</td><td>NVFP4/FP8 对照</td><td>极高</td></tr><tr><td>屏障点位置</td><td>是（权重同步）</td><td>拓扑相关代价</td><td>中</td></tr><tr><td>长尾占比</td><td>否</td><td>验证器侧统计</td><td>高</td></tr></tbody></table>\n<p>一个具体例子：同一扩散采样器在 FP8 与 NVFP4 两条路径上跑同一批提示，若噪声调度固定但量化不同，批内样本的奖励打分方差会不同，进而改变策略更新的梯度估计。此时比较两条路径的“吞吐”没有意义，因为打分分布已经不同——吞吐是手段，分布一致性才是目的。判断标准应落在“随机状态命中率”与“批级打分方差”这两个监控指标上，而非 tokens/s。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-46\">四十六 · batch 与并发：分桶决定了一切数字的分母</h3>\n<p>论文只说“按提示长度分桶并确定批大小”，没有给桶边界。这正是基准口径最容易被做手脚的地方：桶边界一变，批内样本的长度方差就变，前缀共享 KV 的命中率随之变化，吞吐数字立刻不可比。工程上应把分桶策略当作基准的一部分冻结下来，与随机种子记录同级对待。</p>\n<p>批内耦合是这里的关键机制。论文要求批内样本共享前缀 KV 但各自保留随机状态，目的是避免共享缓存导致随机性耦合。代价是：前缀共享带来的 KV 复用收益，与随机状态隔离带来的元数据与调度开销，是一对需要权衡的量。批越大，前缀复用收益越高，但批级屏障的停顿也越长；批越小，随机状态隔离越干净，但 KV 复用率下降、吞吐下滑。</p>\n<div class=\"formula\">$$\\text{有效吞吐}\\approx\\frac{B\\cdot \\bar{L}}{T_{\\text{prefill}}+T_{\\text{sample}}(B)+T_{\\text{barrier}}(B)},\\quad T_{\\text{barrier}}\\propto \\log(\\text{参与同步的 rank 数})$$</div>\n<p>并发口径同样要冻结。论文未给并发上限，部署时若把并发拉到队列饱和，长尾样本会挤占验证器二次推理的窗口，批级吞吐的尾部分布被拉长。可执行的做法是：在 rollout 队列上按 SLO 设定批级屏障点，把并发分成“稳态并发”与“长尾并发”两段统计，分别上报。这样即使绝对数字不可跨部署比较，趋势与失败模式仍可定位。</p>\n<p>具体例子：提示长度分桶若按短/中/长三档切分，短桶批内前缀共享率高但样本短、采样步数占比高，长桶则相反。两个部署若桶边界不同，其“批级吞吐”差异可能完全来自分桶而非引擎效率。因此报告必须附桶边界与各桶占比，否则吞吐数字无法解读。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-47\">四十七 · 指标怎么读：TTFT/TPOT 在扩散 rollout 里的语义偏移</h3>\n<p>TTFT 与 TPOT 原本是为自回归解码定义的。在扩散 rollout 里，这两个指标要重新解释：TTFT 对应“从请求入队到首个去噪步完成并可被奖励模型消费”的时间，TPOT 则对应“批内后续步进与打分聚合的间隔”。论文的分离式预填/解码结构让奖励模型与验证器以独立服务接入，这意味着 TTFT 被拆成 rollout 侧与打分侧两段，只报一个总 TTFT 会掩盖屏障与排队的影响。</p>\n<p>正确的读法是分段上报：rollout 引擎的批级首步延迟、奖励模型服务的预填延迟、验证器二次推理的尾延迟。三者相加不等于端到端，因为异步流水线在权重同步点有屏障，屏障期间的请求处于“已生成未打分”状态，这段等待必须单列。否则 TTFT 的改善可能只是把等待从一段挪到了另一段。</p>\n<ul>\n<li><b>吞吐</b>：必须绑定分桶策略与精度路径，单看 tokens/s 无意义；应同时报批级吞吐与随机状态命中率。</li>\n<li><b>显存</b>：前缀共享 KV 与批级随机状态元数据共同占用；论文未给 KV 策略数值，需按桶统计。</li>\n<li><b>功耗</b>：批级屏障造成的空转是功耗口径里最容易被忽略的一项，屏障越频繁，单位有效样本的能耗越高。</li>\n<li><b>长尾占比</b>：验证器侧单独统计并回写批级记录，是 SLO 判定的直接输入。</li>\n</ul>\n<p>一个具体判断：若某部署报告 TTFT 下降而 TPOT 尾部上升、长尾占比同时上升，最可能的解释是屏障点前移把等待转移到了打分侧，而非引擎真的变快。这类“指标搬家”是扩散 RLHF 基准里最常见的误读。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-48\">四十八 · 哪些提升不可比：四类典型陷阱</h3>\n<p>第一类是<b>精度路径不同</b>。NVFP4 与 FP8 下的采样稳定性未核验，两条路径的奖励打分分布不同，吞吐对比失去意义。第二类是<b>屏障点不同</b>。权重同步点做批级屏障是论文的机制主张，但屏障频率（每批一次还是每若干批一次）未给定；频率一变，off-policy 陈旧样本的泄漏概率就变，打分分布随之变。</p>\n<p>第三类是<b>随机状态记录粒度不同</b>。按请求记录种子与按批记录随机状态是两种粒度，前者可复现单样本，后者只能复现批分布。粒度不同时，“可复现性”这个指标的对比是假的——粒度粗的一方看起来吞吐更高，代价是分布漂移不可追。第四类是<b>长尾处理策略不同</b>。长尾样本进验证器二次推理会拉长尾延迟；若一方把长尾直接丢弃、另一方保留，两者的吞吐与 SLO 都不可比。</p>\n<table class=\"mini\"><thead><tr><th>陷阱</th><th>表现</th><th>判据</th></tr></thead><tbody><tr><td>精度路径</td><td>吞吐高但打分方差大</td><td>须附 NVFP4/FP8 对照与方差</td></tr><tr><td>屏障频率</td><td>TPOT 尾部差异大</td><td>须附屏障点与陈旧样本率</td></tr><tr><td>记录粒度</td><td>可复现性声称不可验</td><td>须附种子/批级记录样例</td></tr><tr><td>长尾策略</td><td>吞吐高但 SLO 不达标</td><td>须附长尾占比与丢弃率</td></tr></tbody></table>\n<p>代价上，这四类陷阱的共同点是：它们都通过改变<b>输入分布</b>而非引擎效率来改变数字。扩散 RLHF 的特殊性在于，采样随机性本身就是输入分布的一部分，所以任何未冻结随机性口径的基准，其数字都不可跨部署比较。这不是保守，而是机制决定的。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-49\">四十九 · 把口径写进监控：可执行的验收清单</h3>\n<p>论文的监控侧上报批级吞吐、随机状态命中率与长尾占比，这三项应直接作为基准报告的必填字段。工程上再补两项：批级打分方差（衡量奖励信号稳定性）与屏障停顿占比（衡量权重同步代价）。五项齐备，数字才具备最低限度的可读性。</p>\n<p>验收清单可以写成伪代码式的判定流程：请求入队时按桶记录批大小与并发；采样时校验随机状态是否随元数据传递、前缀共享 KV 是否做了随机性隔离；打分时校验奖励模型看到的分布是否与当前策略版本一致；屏障点校验是否丢弃了跨版本随机状态；最后按桶汇总五项指标。任一校验失败，该批数字标记为不可比。</p>\n<div class=\"formula\">$$\\text{验收}=\\bigwedge_{i\\in\\{\\text{种子},\\text{隔离},\\text{屏障},\\text{长尾},\\text{方差}\\}}\\text{check}_i(\\text{batch})$$</div>\n<p>具体例子：某批在 NVFP4 路径上跑完，随机状态命中率正常、长尾占比正常，但批级打分方差显著高于同桶 FP8 基线——此时不应报“吞吐提升”，而应报“精度路径导致分布偏移，吞吐数字不可比”，并把该批转入 FP8 路径复测。这正是论文“固定噪声调度”主张在部署侧的落地形态：不是追求某个吞吐数字，而是保证打分分布可复现，让吞吐比较有意义。</p>\n<p>最终落在工程判断上：这套基准口径的价值不在于给出一个可引用的加速比，而在于把“随机性是否被显式控制”变成可验收的布尔量。当随机种子、批内隔离、屏障丢弃三项同时为真，吞吐与显存的数字才有资格进入容量规划；否则再漂亮的数字也只是换了输入分布后的假象。</p>\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-50\">五十 · 迁移到非扩散生成范式时的机制改写</h3>\n<p>这套方案的骨架是“随机状态随请求元数据走、批级屏障隔离版本、前缀共享 KV 与随机性隔离并存”。迁到自回归 LLM 的 RLHF rollout（如 PPO/GRPO 类）时，三类随机性来源的映射关系必须改写：噪声注入退化为采样温度与 top-p/top-k 的截断采样，步进离散化退化为逐 token 的 argmax/采样决策序列，批内耦合则主要来自连续批处理中动态插入的新请求改变了同一 batch 的注意力掩码与位置。此时“固定噪声调度”应改写为“固定采样参数与固定种子到 token 序列的映射”，批级随机状态记录的内容从扩散的噪声张量摘要变为“种子 + 采样参数 + 批内成员序列”。代价上，自回归解码的随机性隔离比扩散更便宜——每个序列天然持有独立 KV，不需要像扩散那样在共享前缀 KV 上额外维护噪声状态；但连续批处理的动态批组成会让“批级屏障”语义变复杂：屏障点不再对应一次完整扩散步，而对应调度器的一次迭代边界。工程判断是：迁移到自回归时保留“种子入元数据 + 版本屏障”两条，放弃“批内噪声状态隔离”这一条，因为它的成本收益在自回归下不成立。</p>\n<p>迁到多模态离散扩散或视频扩散时，情况反过来：批内耦合的权重上升。视频扩散的时序维使前缀共享 KV 的复用粒度从“提示前缀”扩展到“已生成帧”，随机性隔离需要按帧而非按请求切分，缓存路径的元数据膨胀。此时若沿用按请求记录随机状态，长尾样本（长视频、高分辨率）的验证器二次推理会携带巨量状态，显存与带宽代价直接体现在验证器服务的预填阶段。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-51\">五十一 · 与量化精度叠加时的边界</h3>\n<p>论文材料明确未给出量化方案，因此 NVFP4/FP8 下的采样稳定性属于未核验区。可迁移的是控制点，不可迁移的是结论。在 Blackwell 上把该方案与 NVFP4 采样叠加时，需要判断的是：噪声注入在低精度下是否仍保持可复现。NVFP4 的块缩放（block scaling）使同一噪声张量在不同批组成下可能落入不同的缩放因子分组，导致“固定噪声调度”在数值上不再固定。伪代码层面的判断逻辑是：</p>\n<div class=\"formula\">$$\\text{reproducible}(x)=\\big[\\text{seed}(x)=\\text{seed}(x')\\big]\\land\\big[\\text{scale-group}(x)=\\text{scale-group}(x')\\big]$$</div>\n<p>即仅固定种子不足以保证可复现，还需固定缩放分组所依赖的批内数值分布。这意味着在 NVFP4 路径上，批级随机状态记录必须额外携带缩放因子摘要，否则奖励模型看到的样本分布在数值层面漂移。代价是元数据体积与监控上报带宽上升，且缩放分组对批组成敏感，会与“按提示长度分桶”的调度策略冲突——分桶改变了批内数值分布，进而改变缩放分组。工程判断：在 NVFP4 rollout 上，要么把随机性隔离下沉到单样本粒度（放弃批内共享带来的吞吐），要么接受批级可复现而非样本级可复现，把可复现性承诺的粒度写进 SLO 而不是默认样本级。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-52\">五十二 · 规模上限：屏障频率与长尾吞吐的张力</h3>\n<p>该方案的规模上限不在单卡算力，而在屏障频率与长尾样本占比的乘积。异步流水线在权重同步点做批级屏障，屏障越频繁，跨版本随机状态被丢弃的窗口越小，奖励信号越干净；但每次屏障都会清空在途批的随机状态记录，使长尾样本（进入验证器二次推理的那部分）的二次推理结果可能落在屏障另一侧而被丢弃，形成有效吞吐损失。设屏障周期为 $T_b$，长尾样本的平均二次推理时延为 $T_v$，则长尾样本被丢弃的概率近似随 $T_v/T_b$ 上升。这不是可忽略的尾部效应：长尾占比越高、验证器越慢，屏障就越像一台吞吐税。</p>\n<p>规模上限因此表现为：当长尾占比与验证器时延使丢弃率超过可接受阈值时，继续扩大批大小与并发不会提升有效吞吐，只会增加被丢弃的重算量。工程上的判断是给屏障点分级——权重同步用强屏障（丢弃跨版本状态），而验证器回写用弱屏障（允许同版本内的状态合并），把强屏障频率压到与权重更新频率同阶，而不是与批调度迭代同阶。这一改动不改变论文的机制内核，但决定了方案能否在 GB200 NVL72 这种高并发档位上线性扩展。材料未给出长尾占比与验证器时延数字，因此上限的具体位置需在部署侧以监控侧的“长尾占比 + 随机状态命中率”两个指标实测标定，而不是照搬论文的批大小设定。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-53\">五十三 · 不适用的场景与判断线</h3>\n<p>三类场景应明确判定为不适用或需大幅改造。其一，单样本、低并发的离线打分场景：批级屏障与随机状态记录的固定开销占比过高，收益被摊销掉，直接用固定种子逐样本串行即可。其二，奖励模型与策略模型强耦合、共享同一推理实例的场景：分离式预填/解码的前提是服务解耦，若二者共享 KV 缓存路径，随机性隔离与缓存复用无法同时成立，必须先在架构上拆开。其三，对可复现性要求低于对吞吐要求的场景（如仅做在线探索、奖励信号容忍噪声）：批级随机状态记录与屏障带来的元数据与同步开销是纯成本，此时应退化为固定种子加定期重放校验，把可复现性做成抽检而非默认。</p>\n<p>判断线可以写成一条工程准则：当“奖励信号跨批次漂移造成的策略更新方差”大于“屏障与状态记录带来的吞吐损失”时，该方案值得部署；反之应简化。前者可由批级吞吐与随机状态命中率的联合监控间接反映，后者由屏障周期与长尾丢弃率直接度量。论文未给出消融，因此这条准则的阈值只能由部署方用自己的负载形态标定，不能引用论文结论。</p>\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-54\">五十四 · 跨领域迁移的形态差异</h3>\n<p>迁到代码生成或数学推理的 RLHF 时，rollout 的随机性主要体现为采样多样性对验证器通过率的影响，而非扩散噪声。此时“批内耦合”的来源变成验证器服务的批聚合打分——同一批内不同样本共享验证器实例的批维度，若验证器对批内顺序敏感（如批归一化式的统计），样本打分就不再独立。该方案的前缀共享 KV 隔离思路可迁移为“验证器批聚合的样本独立性隔离”，但代价从 KV 显存转移到验证器预填阶段的批统计维护。迁到推荐或广告的生成式排序时，长尾样本占比通常远高于对话场景，屏障丢弃率的张力被放大，规模上限会更早出现。</p>\n<p>跨领域迁移的统一判断是：该方案真正可迁移的内核只有两条——随机状态随请求走、版本屏障隔离陈旧样本；其余（噪声调度固定、批内噪声隔离、前缀 KV 隔离的具体实现）都依赖生成范式与缓存拓扑，必须按目标领域重写。把内核与实现分开，是判断“能不能迁”的唯一可靠方式；把实现当内核照搬，就会在 NVFP4 缩放分组、连续批处理动态批组成、验证器批统计这些地方撞上不适用的边界。</p>\n\n\n<h3 id=\"paper-understanding-sampler-stochasticity-2025-sec-55\">五十五 · 边界判定：随机性控制方案的适用域与失效条件</h3>\n<p>这套方案的第一道边界在采样器族本身。噪声注入、步进离散化、批内耦合这三类拆分成立的前提，是采样过程能被显式地参数化为“调度 + 状态 + 缓存路径”三件可记录的东西——DDIM、Euler 系、DPM-Solver 这类确定性骨干加显式噪声调度的采样器天然适配，因为随机种子写进请求元数据后，重放路径是闭合的。换成 SDE 型采样或带自适应步长的求解器，步进离散化不再是预设常量而是随样本状态漂移的变量，批级随机状态记录就从“记录种子”退化为“记录整条轨迹”，元数据体积与回写带宽随步数线性增长。此时单批的元数据开销可按 <span class=\"formula\">$$M_{\\text{batch}} \\approx B \\cdot S \\cdot \\left| \\xi \\right|$$</span> 估算（B 为批大小、S 为有效步数、|ξ| 为单步状态编码宽度），当 S 上升到数十步量级、B 又按提示长度分桶后拉大，元数据本身会挤占 rollout 引擎的 HBM 带宽预算，与 KV 复用争抢同一条通路。工程判断很直接：自适应步长采样器要么放弃批级状态记录、退回固定调度，要么把状态记录下沉到验证器侧异步补录，代价是奖励打分的可复现性从“批内即时”降为“事后对齐”。</p>\n<p>第二道边界在奖励模型与验证器的接入形态。分离式预填/解码之所以能吃到这套方案的红利，是因为它把打分拆成两个可独立屏障的相位，权重同步点落在相位之间而不打断采样。若奖励模型是单体式同步调用——请求进来即阻塞等待打分返回——批级屏障就无处安放，只能退化为请求级锁，异步流水线的吞吐被串行化。更麻烦的是长尾样本的二次推理：验证器回写批级随机状态记录时，若该批已被屏障丢弃（跨版本），回写就变成孤儿记录，监控侧的“随机状态命中率”会系统性偏低，SLO 判定把正常的版本切换误判为随机性失控。这类失效不体现在单次延迟上，而体现在监控指标的语义漂移上，属于典型的“机制正确、观测错误”。</p>\n<p>第三道边界是规模上限，且上限不在算力而在屏障粒度。批级屏障的隔离强度与批大小成正比、与权重同步频率成反比：同步越频繁，被丢弃的跨版本随机状态越多，rollout 的有效样本产出率下降；批越大，单次屏障的等待窗口越长，长尾样本在窗口内堆积。设同步周期为 T、批级屏障等待为 W，则有效吞吐大致按 <span class=\"formula\">$$\\text{Throughput}_{\\text{eff}} \\propto \\frac{T - W}{T}$$</span> 衰减，W 又随批内最长尾样本的验证器二次推理时延上升。这意味着该方案在“短提示、大批量、低频同步”的负载下最稳，一旦提示长度分布长尾化、验证器成为瓶颈，屏障就从隔离机制变成吞吐税。迁移到 Blackwall 部署时，NVFP4 采样稳定性本身未被材料量化，固定噪声调度能否在低精度下维持分布可复现属于未核验项；可迁移的是批级随机状态与屏障这套控制面思路，不可直接迁移的是“低精度下随机性等价”这一隐含假设。跨领域迁移到非 RLHF 的批量生成场景（如批量图像采样服务）时，奖励模型与验证器不存在，批级屏障失去隔离对象，方案退化为纯粹的种子记录与缓存隔离，收益从“奖励信号稳定”降为“结果可重放”，系统代价却照付——这是判断是否值得迁移的分水岭。</p>\n<table class=\"mini\"><thead><tr><th>迁移维度</th><th>可直接迁移</th><th>需改造</th><th>不适用</th></tr></thead><tbody><tr><td>采样器族</td><td>固定噪声调度的确定性骨干</td><td>自适应步长需改状态编码</td><td>SDE 型高步数轨迹记录</td></tr><tr><td>服务形态</td><td>分离式预填/解码 + 批级屏障</td><td>单体同步奖励模型需拆相位</td><td>无验证器的纯生成服务</td></tr><tr><td>规模</td><td>短提示、大批、低频同步</td><td>长尾提示需调屏障周期</td><td>验证器成为瓶颈的负载</td></tr></tbody></table>\n<figure class=\"diagram\" data-fig=\"paper-family\"><svg style=\"max-width:746px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 746.0 138\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><text x=\"136.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">上游 · 站在谁肩上</text><rect x=\"38.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><text x=\"48.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#b45309\" font-weight=\"500\" text-anchor=\"start\">领域入口（无上游）</text><text x=\"380.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">本文</text><rect x=\"282.0\" y=\"44.0\" width=\"196.0\" height=\"52.0\" rx=\"6\" fill=\"#e9eff5\" stroke=\"#d6e2ec\" stroke-width=\"1.2\"/><text x=\"292.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Understanding Sampler </text><text x=\"292.0\" y=\"78.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#163a5a\" font-weight=\"500\" text-anchor=\"start\">Stochasticity in …</text><text x=\"624.0\" y=\"32.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"10.5\" fill=\"#68727d\" font-weight=\"600\" text-anchor=\"middle\">下游 · 被谁接走</text><rect x=\"526.0\" y=\"44.0\" width=\"196.0\" height=\"35.0\" rx=\"6\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><text x=\"536.0\" y=\"61.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"12.0\" fill=\"#15803d\" font-weight=\"500\" text-anchor=\"start\">暂无下游记录</text><line x1=\"238.0\" y1=\"74.0\" x2=\"271.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 270.0 69.5 L 270.0 78.5 L 278.0 74.0 Z\" fill=\"#d8d3c6\"/><line x1=\"482.0\" y1=\"74.0\" x2=\"515.0\" y2=\"74.0\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 514.0 69.5 L 514.0 78.5 L 522.0 74.0 Z\" fill=\"#d8d3c6\"/><text x=\"380.0\" y=\"128.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.0\" fill=\"#68727d\" font-weight=\"400\" text-anchor=\"middle\">2025 · arXiv preprint</text></svg><figcaption><b>家谱</b> · Understanding Sampler S… 的上游问题、本文位置与下游继承；箭头表示方法/问题的传递，不是时间先后。</figcaption></figure>\n<table class=\"mini\" data-fig=\"paper-exp\"><caption>实验速查：这篇论文拿什么数据、和谁比、提升来自哪里</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>数据集</td><td>未给出</td></tr><tr><td>基线</td><td>未给出</td></tr><tr><td>主要结果</td><td>论文未给出可核验的数据规模与吞吐数字；材料仅表明采样随机性会改变奖励打分分…</td></tr><tr><td>消融</td><td>材料未给出消融实验；仅可推断固定噪声调度与批级随机状态记录是控制随机性的关…</td></tr><tr><td>局限</td><td>材料未给出硬件档位、并行拓扑与量化方案；NVFP4下采样稳定性、长尾样本吞…</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：papers/paper-understanding-sampler-stochasticity-2025 · 共 9 个片段</p>\n";break;}}})();
